
import React from 'react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  children: React.ReactNode;
  title?: string;
}

const Modal: React.FC<ModalProps> = ({ isOpen, onClose, children, title }) => {
  if (!isOpen) return null;

  return (
    <div 
      className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center p-3 sm:p-4"
      onClick={onClose}
    >
      <div 
        className="bg-white dark:bg-slate-800 rounded-xl shadow-2xl w-full max-w-[94vw] sm:max-w-2xl lg:max-w-3xl max-h-[80dvh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="p-4 sm:p-5 md:p-6">
          {title && (
            <div className="mb-6 pb-4 border-b border-gray-200 dark:border-gray-600">
              <h2 className="text-xl sm:text-2xl font-bold text-gray-900 dark:text-white text-center">
                {title}
              </h2>
            </div>
          )}
          {children}
        </div>
      </div>
    </div>
  );
};

export default Modal;
