import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { doc, updateDoc } from 'firebase/firestore';
import { db } from '../services/firebase';
import { useAuthState } from 'react-firebase-hooks/auth';
import { auth } from '../services/firebase';
import { CheckCircleIcon } from './Icons';
import { dataServiceRouter } from '../services/dataServiceRouter';

const SuccessPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [user] = useAuthState(auth);
  const [processing, setProcessing] = useState(true);
  const [success, setSuccess] = useState(false);
  
  const sessionId = searchParams.get('session_id');
  const plan = searchParams.get('plan');

  useEffect(() => {
    const updateUserPlan = async () => {
      if (user && sessionId && plan) {
        try {
          // Calcular fecha de expiración
          const now = new Date();
          const expirationDate = new Date(now);
          
          if (plan === 'yearly') {
            expirationDate.setFullYear(now.getFullYear() + 1);
          } else {
            expirationDate.setMonth(now.getMonth() + 1);
          }

          // Actualizar usuario en Firestore
          await updateDoc(doc(db, 'users', user.uid), {
            plan: 'premium',
            subscriptionStatus: 'active',
            subscriptionType: plan,
            subscriptionStart: now,
            subscriptionEnd: expirationDate,
            stripeSessionId: sessionId,
            updatedAt: now
          });

          const cloudActivation = await dataServiceRouter.activatePremiumCloudMode();
          if (!cloudActivation.success) {
            console.warn('[SuccessPage] No se pudo activar modo cloud automáticamente:', cloudActivation.message);
          }

          setSuccess(true);
        } catch (error) {
          console.error('Error al actualizar el plan del usuario:', error);
        }
      }
      setProcessing(false);
    };

    updateUserPlan();
  }, [user, sessionId, plan]);

  if (processing) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600 mx-auto mb-4"></div>
          <p className="text-lg text-gray-600">Procesando tu suscripción...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-lg shadow-lg p-8 text-center">
        {success ? (
          <>
            <CheckCircleIcon className="w-16 h-16 text-green-500 mx-auto mb-4" />
            <h1 className="text-2xl font-bold text-gray-900 mb-4">¡Pago Exitoso!</h1>
            <p className="text-gray-600 mb-6">
              Tu suscripción {plan === 'yearly' ? 'anual' : 'mensual'} ha sido activada correctamente.
            </p>
            <button
              onClick={() => window.location.href = '/dashboard'}
              className="w-full bg-green-600 text-white py-3 px-4 rounded-lg font-semibold hover:bg-green-700 transition-colors"
            >
              Ir al Dashboard
            </button>
          </>
        ) : (
          <>
            <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <span className="text-red-600 text-2xl">✕</span>
            </div>
            <h1 className="text-2xl font-bold text-gray-900 mb-4">Error en el Pago</h1>
            <p className="text-gray-600 mb-6">
              Hubo un problema al procesar tu suscripción. Por favor, contacta con soporte.
            </p>
            <button
              onClick={() => window.location.href = '/settings'}
              className="w-full bg-gray-600 text-white py-3 px-4 rounded-lg font-semibold hover:bg-gray-700 transition-colors"
            >
              Volver a Configuración
            </button>
          </>
        )}
      </div>
    </div>
  );
};

export default SuccessPage;
