import React, { useState, useMemo, useEffect } from 'react';
import { Reward, RewardClaim, RewardStatus, NewRewardPayload, User, Home, LimitType } from '../types';
import { useSubscription } from '../hooks/useSubscription';
import { PlusIcon, PencilIcon, TrashIcon, GiftIcon, CheckIcon, XMarkIcon } from './Icons';
import Modal from './Modal';
import { useI18n } from '../i18n/I18nProvider';

interface RewardsPageProps {
  currentUser: User;
  currentHome: Home;
  users: User[];
  rewards: Reward[];
  rewardClaims: RewardClaim[];
  createReward: (rewardData: NewRewardPayload, creatorId: string) => Promise<void>;
  updateReward: (rewardId: string, updates: Partial<Reward>) => Promise<void>;
  deleteReward: (rewardId: string) => Promise<void>;
  claimReward: (rewardId: string, userId: string) => Promise<{ success: boolean; message: string }>;
  processRewardClaim: (claimId: string, status: RewardStatus, processedBy: string, notes?: string) => Promise<void>;
  getUserPointsInHome: (userId: string, homeId: string) => Promise<number>;
  onLimitReached: (reason: string) => void;
}

const RewardsPage: React.FC<RewardsPageProps> = ({
  currentUser,
  currentHome,
  users = [],
  rewards = [],
  rewardClaims = [],
  createReward,
  updateReward,
  deleteReward,
  claimReward,
  processRewardClaim,
  getUserPointsInHome,
  onLimitReached
}) => {
  const { t } = useI18n();
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [editingReward, setEditingReward] = useState<Reward | null>(null);
  const [userPoints, setUserPoints] = useState<number>(0);
  const [selectedClaimUserId, setSelectedClaimUserId] = useState<string>(currentUser.id);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [activeTab, setActiveTab] = useState<'available' | 'myClaims' | 'manageClaims'>('available');
  
  // Nuevo estado para el modal de rechazo
  const [rejectModal, setRejectModal] = useState<{ isOpen: boolean; claimId: string | null }>({ isOpen: false, claimId: null });
  const [rejectNotes, setRejectNotes] = useState('');
  const { checkLimit, isPremium } = useSubscription(currentUser, [], currentHome);
  const isAdmin = currentHome.adminIds.includes(currentUser.id);
  const membersInHome = useMemo(
    () => users.filter(u => currentHome.memberIds.includes(u.id)),
    [users, currentHome.memberIds]
  );
  const effectiveClaimUserId = isPremium ? currentUser.id : selectedClaimUserId;
  const effectiveClaimUser = membersInHome.find(u => u.id === effectiveClaimUserId) || currentUser;

  useEffect(() => {
    if (isPremium) return;
    if (!membersInHome.length) return;
    const exists = membersInHome.some(u => u.id === selectedClaimUserId);
    if (!exists) {
      setSelectedClaimUserId(membersInHome[0].id);
    }
  }, [isPremium, membersInHome, selectedClaimUserId]);
  
  const homeRewards = useMemo(() => 
    rewards.filter(r => r.homeId === currentHome.id && r.isActive),
    [rewards, currentHome.id]
  );
  
  const pendingClaims = useMemo(() => 
    rewardClaims.filter(c => c.homeId === currentHome.id && c.status === RewardStatus.PENDING),
    [rewardClaims, currentHome.id]
  );
  
  const userClaims = useMemo(() => 
    rewardClaims.filter(c => c.userId === effectiveClaimUserId && c.homeId === currentHome.id)
      .sort((a, b) => new Date(b.claimedAt).getTime() - new Date(a.claimedAt).getTime()),
    [rewardClaims, effectiveClaimUserId, currentHome.id]
  );

  useEffect(() => {
    const loadUserPoints = async () => {
      try {
        const points = await getUserPointsInHome(effectiveClaimUserId, currentHome.id);
        setUserPoints(points);
      } catch (error) {
        console.error('Error loading user points:', error);
      }
    };
    loadUserPoints();
  }, [effectiveClaimUserId, currentHome.id, getUserPointsInHome]);

  const handleCreateReward = async (data: NewRewardPayload) => {
    try {
      if (!checkLimit(LimitType.REWARDS)) {
        onLimitReached(t('rewards.limitReached'));
        return;
      }
      await createReward(data, currentUser.id);
      setShowCreateModal(false);
      showMessage('success', t('rewards.createdSuccess'));
    } catch (error) {
      showMessage('error', t('rewards.createdError'));
    }
  };

  const handleEditReward = async (data: NewRewardPayload) => {
    if (!editingReward) return;
    try {
      await updateReward(editingReward.id, data);
      setEditingReward(null);
      showMessage('success', t('rewards.updatedSuccess'));
    } catch (error) {
      showMessage('error', t('rewards.updatedError'));
    }
  };

  const handleDeleteReward = async (rewardId: string) => {
    try {
      console.log('[DEBUG] Mostrando confirmación para eliminar premio:', rewardId);
      const confirmed = window.confirm(t('rewards.confirmDelete'));
      console.log('[DEBUG] Usuario confirmó:', confirmed);
      
      if (!confirmed) {
        console.log('[DEBUG] Eliminación cancelada por el usuario');
        return;
      }
      
      console.log('[DEBUG] Procediendo a eliminar premio...');
      await deleteReward(rewardId);
      showMessage('success', t('rewards.deletedSuccess'));
      console.log('[DEBUG] Premio eliminado exitosamente');
    } catch (error) {
      console.error('[ERROR] Error al eliminar premio:', error);
      showMessage('error', t('rewards.deletedError'));
    }
  };

  const handleClaimReward = async (rewardId: string) => {
    try {
      // Calcular puntos disponibles considerando solicitudes pendientes
      const pendingPoints = userClaims
        .filter(claim => claim.status === RewardStatus.PENDING)
        .reduce((total, claim) => total + claim.pointsSpent, 0);
      
      const availablePoints = userPoints - pendingPoints;
      const reward = rewards.find(r => r.id === rewardId);
      
      if (!reward) {
        showMessage('error', t('rewards.notFound'));
        return;
      }
      
      if (availablePoints < reward.pointsCost) {
        showMessage('error', t('rewards.insufficientPointsDetailed', { total: userPoints, pending: pendingPoints, available: availablePoints }));
        return;
      }
      
      const result = await claimReward(rewardId, effectiveClaimUserId);
      if (result.success) {
        showMessage('success', result.message);
        // Actualizar puntos del usuario
        const newPoints = await getUserPointsInHome(effectiveClaimUserId, currentHome.id);
        setUserPoints(newPoints);
      } else {
        showMessage('error', result.message);
      }
    } catch (error) {
      showMessage('error', t('rewards.claimError'));
    }
  };

  const handleProcessClaim = async (claimId: string, status: RewardStatus, notes?: string) => {
    try {
      await processRewardClaim(claimId, status, currentUser.id, notes);
      showMessage('success', t('rewards.claimProcessed', { status: status.toLowerCase() }));
    } catch (error) {
      showMessage('error', t('rewards.claimProcessError'));
    }
  };

  const handleCancelClaim = async (claimId: string) => {
    if (window.confirm(t('rewards.confirmCancelClaim'))) {
      try {
        await processRewardClaim(claimId, RewardStatus.REJECTED, currentUser.id, t('rewards.canceledByUser'));
        showMessage('success', t('rewards.claimCanceled'));
      } catch (error) {
        showMessage('error', t('rewards.claimCancelError'));
      }
    }
  };

  const showMessage = (type: 'success' | 'error', text: string) => {
    setMessage({ type, text });
    setTimeout(() => setMessage(null), 5000);
  };

  const getStatusColor = (status: RewardStatus) => {
    switch (status) {
      case RewardStatus.PENDING:
        return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200';
      case RewardStatus.GRANTED:
        return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200';
      case RewardStatus.REJECTED:
        return 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200';
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200';
    }
  };

    const handleRejectClaim = (claimId: string) => {
        setRejectModal({ isOpen: true, claimId });
        setRejectNotes('');
    };

    const confirmRejectClaim = async () => {
        if (rejectModal.claimId) {
        await handleProcessClaim(rejectModal.claimId, RewardStatus.REJECTED, rejectNotes || undefined);
        setRejectModal({ isOpen: false, claimId: null });
        setRejectNotes('');
        }
    };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 pb-20">
      {/* Header con puntos del usuario */}
      <div className="bg-gradient-to-r from-primary-500 to-primary-600 rounded-xl p-6 mb-6 text-white">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2">
              <GiftIcon className="w-8 h-8" />
              {t('rewards.title')}
            </h1>
            <p className="text-primary-100 mt-1">
              {isPremium ? t('rewards.subtitle.premium') : t('rewards.subtitle.free', { name: effectiveClaimUser.name })}
            </p>
          </div>
          <div className="text-right">
            <div className="text-3xl font-bold">{userPoints}</div>
            <div className="text-primary-100 text-sm">{t('rewards.availablePoints')}</div>
          </div>
        </div>
        {!isPremium && (
          <div className="mt-3 rounded-lg bg-white/8 border border-white/15 px-3 py-2.5 sm:px-4 sm:py-3 backdrop-blur-sm max-w-md">
            <div className="flex items-center justify-between gap-3">
              <label className="text-xs sm:text-sm font-semibold text-white/90 tracking-wide">{t('rewards.redeemAs')}</label>
              <span className="text-[11px] sm:text-xs text-white/70">{t('rewards.member')}</span>
            </div>
            <div className="relative mt-1.5 sm:mt-2">
              <div className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 flex items-center gap-2">
                <span className="h-2 w-2 rounded-full bg-cyan-200/90"></span>
              </div>
              <select
                value={selectedClaimUserId}
                onChange={(e) => setSelectedClaimUserId(e.target.value)}
                className="w-full appearance-none rounded-md bg-primary-50/95 text-primary-900 border border-primary-200/70 pl-8 pr-10 py-2 text-sm shadow-sm focus:outline-none focus:ring-2 focus:ring-cyan-200/80 focus:border-cyan-100"
              >
                {membersInHome.map(member => (
                  <option key={member.id} value={member.id}>{member.name}</option>
                ))}
              </select>
              <svg
                className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-primary-500"
                viewBox="0 0 20 20"
                fill="currentColor"
                aria-hidden="true"
              >
                <path fillRule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 011.08 1.04l-4.25 4.51a.75.75 0 01-1.08 0l-4.25-4.51a.75.75 0 01.02-1.06z" clipRule="evenodd" />
              </svg>
            </div>
          </div>
        )}
      </div>

      {/* Mensajes */}
      {message && (
        <div className={`mb-4 p-4 rounded-lg ${
          message.type === 'success' 
            ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
            : 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200'
        }`}>
          {message.text}
        </div>
      )}

      {/* Tabs */}
      <div className="flex space-x-1 mb-6 bg-gray-100 dark:bg-gray-800 p-1 rounded-lg">
        <button
          onClick={() => setActiveTab('available')}
          className={`flex-1 py-2 px-4 rounded-md text-sm font-medium transition-colors ${
            activeTab === 'available'
              ? 'bg-white dark:bg-gray-700 text-primary-600 dark:text-primary-400 shadow-sm'
              : 'text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white'
          }`}
        >
          {t('rewards.tab.available')}
        </button>
        <button
          onClick={() => setActiveTab('myClaims')}
          className={`flex-1 py-2 px-4 rounded-md text-sm font-medium transition-colors relative ${
            activeTab === 'myClaims'
              ? 'bg-white dark:bg-gray-700 text-primary-600 dark:text-primary-400 shadow-sm'
              : 'text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white'
          }`}
        >
          {isPremium ? t('rewards.tab.myClaims') : t('rewards.tab.claimsOf', { name: effectiveClaimUser.name })}
          {userClaims.filter(c => c.status === RewardStatus.PENDING).length > 0 && (
            <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full h-5 w-5 flex items-center justify-center">
              {userClaims.filter(c => c.status === RewardStatus.PENDING).length}
            </span>
          )}
        </button>
        {isAdmin && (
          <button
            onClick={() => setActiveTab('manageClaims')}
            className={`flex-1 py-2 px-4 rounded-md text-sm font-medium transition-colors relative ${
              activeTab === 'manageClaims'
                ? 'bg-white dark:bg-gray-700 text-primary-600 dark:text-primary-400 shadow-sm'
                : 'text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white'
            }`}
          >
            {t('rewards.tab.manageClaims')}
            {pendingClaims.length > 0 && (
              <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full h-5 w-5 flex items-center justify-center">
                {pendingClaims.length}
              </span>
            )}
          </button>
        )}
      </div>

      {/* Contenido según tab activo */}
      {activeTab === 'available' && (
        <div>
          {/* Botón crear premio (solo admins) */}
          {isAdmin && (
            <div className="mb-6">
              <button
                onClick={() => setShowCreateModal(true)}
                className="bg-primary-600 hover:bg-primary-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors"
              >
                <PlusIcon className="w-5 h-5" />
                {t('rewards.create')}
              </button>
            </div>
          )}

          {/* Lista de premios */}
          {homeRewards.length === 0 ? (
            <div className="text-center py-12">
              <GiftIcon className="w-16 h-16 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
                {t('rewards.empty.available')}
              </h3>
              <p className="text-gray-600 dark:text-gray-400">
                {isAdmin ? t('rewards.empty.availableAdmin') : t('rewards.empty.availableMember')}
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {homeRewards.map((reward) => {
                const pendingPoints = userClaims
                  .filter(claim => claim.status === RewardStatus.PENDING)
                  .reduce((total, claim) => total + claim.pointsSpent, 0);
                const availablePoints = userPoints - pendingPoints;
                const canClaim = availablePoints >= reward.pointsCost;
                
                return (
                  <div key={reward.id} className="bg-white dark:bg-gray-800 rounded-lg p-6 border border-gray-200 dark:border-gray-700 hover:shadow-lg transition-shadow">
                    <div className="flex items-start justify-between mb-4">
                      <div className="text-4xl">{reward.emoji}</div>
                      {isAdmin && (
                        <div className="flex space-x-1">
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              e.preventDefault();
                              setEditingReward(reward);
                            }}
                            className="p-1 text-gray-400 hover:text-blue-600 transition-colors"
                            title="Editar premio"
                          >
                            <PencilIcon className="w-4 h-4" />
                          </button>
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              e.preventDefault();
                              handleDeleteReward(reward.id);
                            }}
                            className="p-1 text-gray-400 hover:text-red-600 transition-colors"
                            title="Eliminar premio"
                          >
                            <TrashIcon className="w-4 h-4" />
                          </button>
                        </div>
                      )}
                    </div>
                    
                    <h3 className="font-semibold text-lg text-gray-900 dark:text-white mb-2">
                      {reward.title}
                    </h3>
                    
                    <p className="text-gray-600 dark:text-gray-300 text-sm mb-4">
                      {reward.description}
                    </p>
                    
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-2">
                        <span className="text-2xl font-bold text-primary-600 dark:text-primary-400">
                          {reward.pointsCost}
                        </span>
                        <span className="text-sm text-gray-500 dark:text-gray-400">puntos</span>
                      </div>
                      
                      <button
                        onClick={() => handleClaimReward(reward.id)}
                        disabled={!canClaim}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                          canClaim
                            ? 'bg-primary-600 hover:bg-primary-700 text-white'
                            : 'bg-gray-200 dark:bg-gray-700 text-gray-500 dark:text-gray-400 cursor-not-allowed'
                        }`}
                      >
                        {canClaim ? t('rewards.claim') : 
                          availablePoints < reward.pointsCost && pendingPoints > 0 
                            ? t('rewards.pointsCommitted', { points: pendingPoints })
                            : t('rewards.insufficientPoints')
                        }
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Mis Solicitudes */}
      {activeTab === 'myClaims' && (
        <div>
          <h2 className="text-xl font-semibold mb-4">{t('rewards.tab.myClaims')}</h2>
          {userClaims.length === 0 ? (
            <div className="text-center py-8">
              <GiftIcon className="w-16 h-16 text-gray-400 mx-auto mb-4" />
              <p className="text-gray-600 dark:text-gray-400">{t('rewards.empty.myClaims')}</p>
            </div>
          ) : (
            <div className="space-y-4">
              {userClaims.map((claim) => {
                const reward = rewards.find(r => r.id === claim.rewardId);
                return (
                  <div key={claim.id} className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-3">
                        <span className="text-2xl">{reward?.emoji}</span>
                        <div>
                          <h3 className="font-medium text-gray-900 dark:text-white">{reward?.title}</h3>
                          <p className="text-sm text-gray-600 dark:text-gray-400">
                            {t('rewards.requestedOn')} {new Date(claim.claimedAt).toLocaleDateString()}
                          </p>
                        </div>
                      </div>
                      <div className="text-right">
                        <span className={`inline-flex px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(claim.status)}`}>
                          {claim.status}
                        </span>
                        <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                          {claim.pointsSpent} {t('stats.points')}
                        </p>
                      </div>
                    </div>
                    {claim.notes && (
                      <div className="mt-3 p-3 bg-gray-50 dark:bg-gray-700 rounded-lg">
                        <p className="text-sm text-gray-700 dark:text-gray-300">
                          <strong>{t('rewards.adminNote')}:</strong> {claim.notes}
                        </p>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Gestionar Solicitudes (solo para administradores) */}
      {activeTab === 'manageClaims' && isAdmin && (
        <div>
          <h2 className="text-xl font-semibold mb-4">{t('rewards.tab.manageClaims')}</h2>
          {pendingClaims.length === 0 ? (
            <div className="text-center py-8">
              <GiftIcon className="w-16 h-16 text-gray-400 mx-auto mb-4" />
              <p className="text-gray-600 dark:text-gray-400">{t('rewards.empty.pendingClaims')}</p>
            </div>
          ) : (
            <div className="space-y-4">
              {pendingClaims.map((claim) => {
                const reward = rewards.find(r => r.id === claim.rewardId);
                const user = users.find(u => u.id === claim.userId);
                return (
                  <div key={claim.id} className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700">
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center space-x-3">
                        <span className="text-2xl">{reward?.emoji}</span>
                        <div>
                          <h3 className="font-medium text-gray-900 dark:text-white">{reward?.title}</h3>
                          <p className="text-sm text-gray-600 dark:text-gray-400">
                            {t('rewards.requestedByOn', { name: user?.name || '-' })} {new Date(claim.claimedAt).toLocaleDateString()}
                          </p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="text-lg font-semibold text-primary-600 dark:text-primary-400">
                          {claim.pointsSpent} {t('stats.points')}
                        </p>
                      </div>
                    </div>
                    
                    <div className="flex space-x-2">
                      <button
                        onClick={() => handleProcessClaim(claim.id, RewardStatus.GRANTED)}
                        className="flex-1 bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg flex items-center justify-center gap-2 transition-colors"
                      >
                        <CheckIcon className="w-4 h-4" />
                        {t('rewards.approve')}
                      </button>
                      <button
                        onClick={() => handleRejectClaim(claim.id)}
                        className="flex-1 bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-lg flex items-center justify-center gap-2 transition-colors"
                      >
                        <XMarkIcon className="w-4 h-4" />
                        {t('rewards.reject')}
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}
      {/* Modales */}
      <RewardFormModal
        isOpen={showCreateModal}
        onClose={() => setShowCreateModal(false)}
        onSubmit={handleCreateReward}
        homeId={currentHome.id}
      />
      
      <RewardFormModal
        isOpen={!!editingReward}
        onClose={() => setEditingReward(null)}
        onSubmit={handleEditReward}
        initialData={editingReward}
        homeId={currentHome.id}
      />
      
      {/* Modal de rechazo */}
            {/* Modal de rechazo mejorado */}
      <Modal
        isOpen={rejectModal.isOpen}
        onClose={() => setRejectModal({ isOpen: false, claimId: null })}
        title=""
      >
        <div className="text-center space-y-6">
          {/* Icono de advertencia */}
          <div className="mx-auto flex items-center justify-center w-16 h-16 bg-red-100 dark:bg-red-900/20 rounded-full">
            <XMarkIcon className="w-8 h-8 text-red-600 dark:text-red-400" />
          </div>
          
          {/* Título y descripción */}
          <div>
            <h3 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
              {t('rewards.rejectModal.title')}
            </h3>
            <p className="text-gray-600 dark:text-gray-400">
              {t('rewards.rejectModal.description')}
            </p>
          </div>
          
          {/* Campo de notas */}
          <div className="text-left">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-3">
              {t('rewards.rejectModal.reason')}
            </label>
            <div className="relative">
              <textarea
                value={rejectNotes}
                onChange={(e) => setRejectNotes(e.target.value)}
                placeholder={t('rewards.rejectModal.placeholder')}
                className="w-full px-4 py-3 border-2 border-gray-200 dark:border-gray-600 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-red-500 dark:bg-gray-700 dark:text-white transition-all duration-200 resize-none"
                rows={4}
              />
              <div className="absolute bottom-3 right-3 text-xs text-gray-400">
                {rejectNotes.length}/200
              </div>
            </div>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-2">
              {t('rewards.rejectModal.help')}
            </p>
          </div>
          
          {/* Botones de acción */}
          <div className="flex space-x-3 pt-2">
            <button
              onClick={() => setRejectModal({ isOpen: false, claimId: null })}
              className="flex-1 px-6 py-3 text-gray-700 dark:text-gray-300 bg-gray-100 dark:bg-gray-600 rounded-xl hover:bg-gray-200 dark:hover:bg-gray-500 transition-all duration-200 font-medium"
            >
              {t('common.cancel')}
            </button>
            <button
              onClick={confirmRejectClaim}
              className="flex-1 px-6 py-3 bg-gradient-to-r from-red-500 to-red-600 hover:from-red-600 hover:to-red-700 text-white rounded-xl transition-all duration-200 font-medium shadow-lg hover:shadow-xl transform hover:scale-105"
            >
              {t('rewards.reject')}
            </button>
          </div>
        </div>
      </Modal>

      {/* Modales existentes */}
      <RewardFormModal
        isOpen={showCreateModal}
        onClose={() => setShowCreateModal(false)}
        onSubmit={handleCreateReward}
        homeId={currentHome.id}
      />
      
      <RewardFormModal
        isOpen={!!editingReward}
        onClose={() => setEditingReward(null)}
        onSubmit={handleEditReward}
        initialData={editingReward}
        homeId={currentHome.id}
      />
    </div>
  );
};

// Modal component for creating/editing rewards
interface RewardFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: NewRewardPayload) => Promise<void>;
  initialData?: Reward | null;
  homeId: string;
}

const RewardFormModal: React.FC<RewardFormModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  initialData,
  homeId
}) => {
  const { t } = useI18n();
  const [formData, setFormData] = useState<NewRewardPayload>({
    title: '',
    description: '',
    emoji: '🎁',
    pointsCost: 100,
    homeId,
    isActive: true
  });
  const [pointsInput, setPointsInput] = useState<string>('100');
  const [loading, setLoading] = useState(false);
  const [validationErrors, setValidationErrors] = useState<{
    title?: boolean;
    description?: boolean;
    emoji?: boolean;
    pointsCost?: boolean;
  }>({});
  const [validationMessage, setValidationMessage] = useState<string>('');

  useEffect(() => {
    if (initialData) {
      setFormData({
        title: initialData.title,
        description: initialData.description,
        emoji: initialData.emoji,
        pointsCost: initialData.pointsCost,
        homeId: initialData.homeId,
        isActive: initialData.isActive
      });
      setPointsInput(String(initialData.pointsCost ?? ''));
    } else {
      setFormData({
        title: '',
        description: '',
        emoji: '🎁',
        pointsCost: 100,
        homeId,
        isActive: true
      });
      setPointsInput('100');
    }
  }, [initialData, homeId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Resetear errores anteriores
    setValidationErrors({});
    setValidationMessage('');
    
    // Validar campos obligatorios
    const errors: typeof validationErrors = {};
    const missingFields: string[] = [];
    
    if (!formData.title.trim()) {
      errors.title = true;
      missingFields.push(t('taskForm.field.title'));
    }
    
    if (!formData.emoji.trim()) {
      errors.emoji = true;
      missingFields.push('Emoji');
    }
    
    // Si hay errores, mostrarlos y no continuar
    if (Object.keys(errors).length > 0) {
      setValidationErrors(errors);
      setValidationMessage(t('taskForm.validation.required', { fields: missingFields.join(', ') }));
      return;
    }
    
    setLoading(true);
    try {
      // Convert points input (string) to a number for the payload
      const pointsCostNumber = parseInt(pointsInput.replace(/[^0-9]/g, ''), 10) || 0;
      const payload: NewRewardPayload = {
        ...formData,
        pointsCost: pointsCostNumber,
        homeId
      };
      await onSubmit(payload);
      onClose();
    } catch (error) {
      console.error('Error submitting reward:', error);
    } finally {
      setLoading(false);
    }
  };

  // Iconos reducidos - solo los más populares
  const popularEmojis = ['🎁', '🏆', '🎖️', '🥇', '⭐', '💎', '🎉', '🍕', '🎮', '💰'];

  return (
    <Modal 
      isOpen={isOpen} 
      onClose={onClose} 
      title={initialData ? t('rewards.form.editTitle') : t('rewards.form.createTitle')}
    >
      <form onSubmit={handleSubmit} className="space-y-4 sm:space-y-6">
        {/* Descripción */}
        <p className="text-sm sm:text-base text-gray-600 dark:text-gray-400 text-center">
          {initialData ? t('rewards.form.editDescription') : t('rewards.form.createDescription')}
        </p>

        {/* Mensaje de validación */}
        {validationMessage && (
          <div className="bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 p-3 rounded">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <svg className="h-5 w-5 text-red-500" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                </svg>
              </div>
              <div className="ml-3">
                <p className="text-sm font-medium text-red-800 dark:text-red-200">{validationMessage}</p>
              </div>
            </div>
          </div>
        )}

        {/* Selector de emoji simplificado */}
        <div>
          <label className={`block text-sm font-semibold mb-2 sm:mb-3 ${validationErrors.emoji ? 'text-red-600 dark:text-red-400' : 'text-gray-700 dark:text-gray-300'}`}>
            {t('rewards.form.emojiLabel')} {validationErrors.emoji && <span className="text-red-500">*</span>}
          </label>
          <div className="space-y-3 sm:space-y-4">
            {/* Iconos populares reducidos */}
            <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-3 sm:p-4">
              <p className="text-xs sm:text-sm text-gray-600 dark:text-gray-400 mb-2">{t('rewards.form.popular')}</p>
              <div className="grid grid-cols-5 sm:grid-cols-10 gap-1 sm:gap-2">
                {popularEmojis.map((emoji) => (
                  <button
                    key={emoji}
                    type="button"
                    onClick={() => {
                      setFormData({ ...formData, emoji });
                      if (validationErrors.emoji) {
                        setValidationErrors(prev => ({ ...prev, emoji: false }));
                        setValidationMessage('');
                      }
                    }}
                    className={`p-2 text-lg sm:text-xl rounded-lg border transition-all duration-200 hover:scale-110 flex items-center justify-center ${formData.emoji === emoji
                        ? 'border-primary-500 bg-primary-100 dark:bg-primary-900/30 shadow-md transform scale-110'
                        : 'border-gray-200 dark:border-gray-600 hover:border-primary-300 dark:hover:border-primary-500 bg-white dark:bg-gray-700'
                    }`}
                  >
                    {emoji}
                  </button>
                ))}
              </div>
            </div>
            
            {/* Campo de entrada personalizado */}
            <div className="relative">
              <input
                type="text"
                value={formData.emoji}
                onChange={(e) => {
                  setFormData({ ...formData, emoji: e.target.value });
                  if (validationErrors.emoji && e.target.value.trim()) {
                    setValidationErrors(prev => ({ ...prev, emoji: false }));
                    setValidationMessage('');
                  }
                }}
                className={`w-full px-3 py-2 sm:px-4 sm:py-3 pr-12 sm:pr-16 rounded-lg focus:ring-2 focus:ring-primary-500 dark:bg-gray-700 dark:text-white transition-all duration-200 text-sm sm:text-base ${
                  validationErrors.emoji
                    ? 'border-2 border-red-500 dark:border-red-400 focus:border-red-500'
                    : 'border-2 border-gray-200 dark:border-gray-600 focus:border-primary-500'
                }`}
                placeholder={t('rewards.form.emojiPlaceholder')}
                maxLength={4}
              />
              <div className="absolute right-2 sm:right-3 top-1/2 transform -translate-y-1/2 text-xl sm:text-2xl">
                {formData.emoji}
              </div>
            </div>
            <p className="text-xs text-gray-500 dark:text-gray-400">
              {t('rewards.form.emojiHint')}
            </p>
          </div>
        </div>

        {/* Campo de título */}
        <div>
          <label className={`block text-sm font-semibold mb-2 sm:mb-3 ${validationErrors.title ? 'text-red-600 dark:text-red-400' : 'text-gray-700 dark:text-gray-300'}`}>
            📝 Título del premio {validationErrors.title && <span className="text-red-500">*</span>}
          </label>
          <input
            type="text"
            value={formData.title}
            onChange={(e) => {
              setFormData({ ...formData, title: e.target.value });
              if (validationErrors.title && e.target.value.trim()) {
                setValidationErrors(prev => ({ ...prev, title: false }));
                setValidationMessage('');
              }
            }}
            className={`w-full px-3 py-2 sm:px-4 sm:py-3 rounded-lg focus:ring-2 focus:ring-primary-500 dark:bg-gray-700 dark:text-white transition-all duration-200 text-sm sm:text-base ${
              validationErrors.title
                ? 'border-2 border-red-500 dark:border-red-400 focus:border-red-500'
                : 'border-2 border-gray-200 dark:border-gray-600 focus:border-primary-500'
            }`}
            placeholder="Ej: Noche de película, Cena especial, Día libre..."
            required
          />
        </div>

        {/* Campo de descripción */}
        <div>
          <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2 sm:mb-3">
            📋 Descripción detallada (opcional)
          </label>
          <textarea
            value={formData.description}
            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            className="w-full px-3 py-2 sm:px-4 sm:py-3 border-2 border-gray-200 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 dark:bg-gray-700 dark:text-white transition-all duration-200 resize-none text-sm sm:text-base"
            placeholder="Describe qué incluye este premio y cómo se puede disfrutar..."
            rows={3}
          />
        </div>

        {/* Campo de costo en puntos */}
        <div>
          <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2 sm:mb-3">
            💰 Costo en puntos (opcional)
          </label>
          <div className="relative">
            <input
              type="text"
              inputMode="numeric"
              pattern="[0-9]*"
              value={pointsInput}
              onChange={(e) => {
                // Allow only digits in the input string so user can type freely
                const cleaned = e.target.value.replace(/[^0-9]/g, '');
                setPointsInput(cleaned);
              }}
              className="w-full px-3 py-2 sm:px-4 sm:py-3 pr-12 sm:pr-16 border-2 border-gray-200 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 dark:bg-gray-700 dark:text-white transition-all duration-200 text-sm sm:text-base"
              min="0"
              step="1"
            />
            <div className="absolute right-3 sm:right-4 top-1/2 transform -translate-y-1/2 text-xs sm:text-sm font-medium text-gray-500 dark:text-gray-400">
              pts
            </div>
          </div>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-2">
            💡 Sugerencia: 50-200 puntos para premios pequeños, 500+ para premios especiales
          </p>
        </div>

        {/* Vista previa compacta */}
        <div className="bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-800 dark:to-gray-700 rounded-lg p-3 sm:p-4">
          <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2 sm:mb-3">👀 Vista previa</h4>
          <div className="bg-white dark:bg-gray-800 rounded-lg p-3 sm:p-4 border border-gray-200 dark:border-gray-600">
            <div className="flex items-start justify-between">
              <div className="flex items-center space-x-2 sm:space-x-3 flex-1 min-w-0">
                <span className="text-2xl sm:text-3xl flex-shrink-0">{formData.emoji || '🎁'}</span>
                <div className="min-w-0 flex-1">
                  <h3 className="font-semibold text-gray-900 dark:text-white text-sm sm:text-base truncate">
                    {formData.title || 'Título del premio'}
                  </h3>
                  <p className="text-xs sm:text-sm text-gray-600 dark:text-gray-400 line-clamp-2">
                    {formData.description || 'Descripción del premio'}
                  </p>
                </div>
              </div>
              <div className="text-right flex-shrink-0 ml-2">
                <span className="text-base sm:text-lg font-bold text-primary-600 dark:text-primary-400">
                  {pointsInput !== '' ? Number(pointsInput) : formData.pointsCost}
                </span>
                <span className="text-xs sm:text-sm text-gray-500 dark:text-gray-400 ml-1">pts</span>
              </div>
            </div>
          </div>
        </div>

        {/* Botones de acción */}
        <div className="flex flex-col sm:flex-row space-y-2 sm:space-y-0 sm:space-x-3 pt-4 border-t border-gray-200 dark:border-gray-600">
          <button
            type="button"
            onClick={onClose}
            className="w-full sm:flex-1 px-4 py-2 sm:px-6 sm:py-3 text-gray-700 dark:text-gray-300 bg-gray-100 dark:bg-gray-600 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-500 transition-all duration-200 font-medium text-sm sm:text-base"
          >
            Cancelar
          </button>
          <button
            type="submit"
            disabled={loading || !formData.title.trim()}
            className="w-full sm:flex-1 px-4 py-2 sm:px-6 sm:py-3 bg-gradient-to-r from-primary-500 to-primary-600 hover:from-primary-600 hover:to-primary-700 disabled:from-gray-400 disabled:to-gray-400 text-white rounded-lg transition-all duration-200 font-medium shadow-lg hover:shadow-xl transform hover:scale-105 disabled:transform-none disabled:hover:scale-100 text-sm sm:text-base"
          >
            {loading ? (
              <span className="flex items-center justify-center">
                <svg className="animate-spin -ml-1 mr-2 sm:mr-3 h-4 w-4 sm:h-5 sm:w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Guardando...
              </span>
            ) : (
              `${initialData ? '✏️ Actualizar' : '🎁 Crear Premio'}`
            )}
          </button>
        </div>
      </form>
    </Modal>
  );
};

export default RewardsPage;

