import React, { useState } from 'react';
import Modal from './Modal';

interface CancelSubscriptionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirmCancel: () => Promise<void>;
}

const CancelSubscriptionModal: React.FC<CancelSubscriptionModalProps> = ({ isOpen, onClose, onConfirmCancel }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleConfirmCancel = async () => {
    setError('');
    setLoading(true);
    
    try {
      await onConfirmCancel();
      onClose();
    } catch (err: any) {
      setError(err.message || 'Error al cancelar la suscripción. Inténtalo de nuevo.');
      setLoading(false);
    }
  };

  const handleClose = () => {
    if (!loading) {
      setError('');
      onClose();
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose}>
      <div className="p-6">
        <h2 className="text-xl font-bold mb-4 text-gray-800">Cancelar Membresía Premium</h2>
        
        <div className="mb-6">
          <p className="text-gray-600 mb-4">
            ¿Estás seguro de que quieres cancelar tu membresía premium?
          </p>
          <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-4">
            <p className="text-yellow-800 text-sm">
              <strong>Importante:</strong> Tu membresía seguirá activa hasta el final del período de facturación actual. 
              Después de esa fecha, perderás el acceso a las funciones premium.
            </p>
          </div>
          <ul className="text-sm text-gray-600 space-y-1">
            <li>• Perderás acceso a funciones premium</li>
            <li>• No se realizarán más cobros automáticos</li>
            <li>• Podrás reactivar tu suscripción en cualquier momento</li>
          </ul>
        </div>

        {error && (
          <div className="mb-4 p-3 bg-red-100 border border-red-400 text-red-700 rounded">
            {error}
          </div>
        )}

        <div className="flex justify-end space-x-3">
          <button
            onClick={handleClose}
            disabled={loading}
            className="px-4 py-2 text-gray-600 bg-gray-200 rounded hover:bg-gray-300 disabled:opacity-50"
          >
            Mantener Suscripción
          </button>
          <button
            onClick={handleConfirmCancel}
            disabled={loading}
            className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 disabled:opacity-50 flex items-center"
          >
            {loading ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                Cancelando...
              </>
            ) : (
              'Confirmar Cancelación'
            )}
          </button>
        </div>
      </div>
    </Modal>
  );
};

export default CancelSubscriptionModal;