import { useEffect, useState } from 'react';
import { AppConfig } from '../types';
import { appConfigService, DEFAULT_APP_CONFIG } from '../services/appConfigService';

export const useAppConfig = () => {
  const [appConfig, setAppConfig] = useState<AppConfig>(() => appConfigService.getCachedConfig() || DEFAULT_APP_CONFIG);
  const [loading, setLoading] = useState<boolean>(!appConfigService.getCachedConfig());
  const [error, setError] = useState<string | null>(null);

  const refresh = async (forceRefresh = false) => {
    setLoading(true);
    setError(null);
    try {
      const config = await appConfigService.getConfig(forceRefresh);
      setAppConfig(config);
      return config;
    } catch (err: any) {
      setError(err?.message || 'No se pudo cargar la configuración.');
      return appConfig;
    } finally {
      setLoading(false);
    }
  };

  const save = async (nextConfig: AppConfig, adminPassword?: string) => {
    setLoading(true);
    setError(null);
    try {
      const result = await appConfigService.saveConfig(nextConfig, adminPassword);
      setAppConfig(result.config);
      return result;
    } catch (err: any) {
      const message = err?.message || 'No se pudo guardar la configuración.';
      setError(message);
      return { success: false, message, config: appConfig };
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void refresh(false);
  }, []);

  return {
    appConfig,
    loading,
    error,
    refresh,
    save,
  };
};
