import React from 'react';
import { User, View, Home } from '../types';
import { PlusIcon, ChartBarIcon, ListBulletIcon, SunIcon, MoonIcon, Cog6ToothIcon, ArrowRightOnRectangleIcon, GiftIcon } from './Icons';
import InstallApp from './InstallApp';
import { useI18n } from '../i18n/I18nProvider';

const CrownMark: React.FC<{ className?: string }> = ({ className }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.8"
    className={className || 'w-5 h-5'}
  >
    <path strokeLinecap="round" strokeLinejoin="round" d="M3 6.5l4.8 4.8L12 5.8l4.2 5.5L21 6.5l-2.3 11.2H5.3L3 6.5Z" />
    <path strokeLinecap="round" strokeLinejoin="round" d="M5.5 17.7h13" />
  </svg>
);

interface HeaderProps {
  currentUser: User;
  isPremium: boolean;
  currentHome: Home | undefined;
  userHomes: Home[];
  onHomeChange: (homeId: string) => void;
  currentView: View;
  onViewChange: (view: View) => void;
  onNewTaskClick: () => void;
  onLogout: () => void;
  theme: string;
  onToggleTheme: () => void;
  onRegisterAnonymous?: () => void;
  disableSettingsNavigation?: boolean;
}

const Header: React.FC<HeaderProps> = ({
  currentUser,
  isPremium,
  currentHome,
  userHomes,
  onHomeChange,
  currentView,
  onViewChange,
  onNewTaskClick,
  onLogout,
  theme,
  onToggleTheme,
  onRegisterAnonymous,
  disableSettingsNavigation = false
}) => {
  const { t } = useI18n();
  const rewardsDisabled = !currentHome;
  const expiryMs = typeof currentUser.subscriptionExpiryTime === 'number'
    ? currentUser.subscriptionExpiryTime
    : (currentUser.subscriptionEndsAt ? Date.parse(currentUser.subscriptionEndsAt) : NaN);
  const premiumDaysRemaining = Number.isFinite(expiryMs) && expiryMs > Date.now()
    ? Math.ceil((expiryMs - Date.now()) / (1000 * 60 * 60 * 24))
    : null;
  const showPremiumRenewButton = isPremium && premiumDaysRemaining !== null && premiumDaysRemaining <= 5;

  const handleLogoClick = () => {
    const isNative = typeof window !== 'undefined' && !!(window as any).Capacitor?.isNativePlatform?.();
    if (!isNative) {
      void Promise.resolve(onLogout());
      return;
    }

    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };

  return (
    <>
      {/* Barra superior */}
      <header
        className="sticky top-0 z-30 bg-white/80 dark:bg-slate-900/80 shadow-md backdrop-blur-sm"
        style={{ paddingTop: 'calc(env(safe-area-inset-top, 0px) + 0.75rem)' }}
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center space-x-4">
              <h1 
                onClick={handleLogoClick}
                className="text-lg sm:text-xl font-bold text-primary-600 dark:text-primary-400 cursor-pointer hover:text-primary-700 dark:hover:text-primary-300 transition-colors select-none"
                title={t('header.home')}
              >
                HouseZen
              </h1>

              {/* Selector de casa */}
              {userHomes.length > 0 && (
                <select
                  value={currentHome?.id || ''}
                  onChange={(e) => onHomeChange(e.target.value)}
                  className="pl-2 pr-2 py-1 bg-white dark:bg-slate-800 border border-primary-200 dark:border-primary-700 rounded-lg text-sm font-semibold focus:ring-2 focus:ring-primary-500 cursor-pointer shadow-sm max-w-[160px] sm:max-w-xs"
                >
                  {userHomes.map((home) => (
                    <option key={home.id} value={home.id}>
                      {home.name}
                    </option>
                  ))}
                </select>
              )}
            </div>

            <div className="flex items-center space-x-2">
              {/* Botón de tema */}
              <button
                onClick={onToggleTheme}
                className="p-2 text-slate-600 hover:text-slate-900 dark:text-slate-300 dark:hover:text-white transition-colors rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800"
                title={theme === 'dark' ? t('header.theme.light') : t('header.theme.dark')}
              >
                {theme === 'dark' ? <SunIcon className="w-5 h-5" /> : <MoonIcon className="w-5 h-5" />}
              </button>

              {isPremium && !showPremiumRenewButton ? (
                <div
                  className="inline-flex items-center justify-center p-2 rounded-full bg-gradient-to-r from-yellow-400 via-amber-500 to-yellow-600 text-white shadow-lg"
                  title={t('header.premium.active')}
                >
                  <CrownMark className="w-5 h-5" />
                </div>
              ) : (
                <div className="flex flex-col items-end mr-1">
                  <button
                    onClick={onRegisterAnonymous}
                    className="inline-flex items-center justify-center px-4 py-2 bg-gradient-to-r from-yellow-400 via-amber-500 to-yellow-600 text-white text-xs sm:text-sm font-bold rounded-md shadow-lg hover:shadow-2xl transition-all duration-300 relative overflow-hidden before:absolute before:inset-0 before:bg-white/20 before:opacity-0 hover:before:opacity-100 before:transition-opacity"
                    title={t('header.premium.view')}
                  >
                    <span className="relative z-10">{t('header.premium.view')}</span>
                  </button>
                  {showPremiumRenewButton && (
                    <span className="mt-1 inline-flex items-center gap-1 text-[10px] font-semibold text-amber-600 dark:text-amber-400 leading-none">
                      <CrownMark className="w-3.5 h-3.5" />
                      {t('header.premium.daysRemaining', { days: premiumDaysRemaining || 0 })}
                    </span>
                  )}
                </div>
              )}
              {!!currentUser?.email && !currentUser?.isAnonymous && (
                <button
                  onClick={onLogout}
                  className="p-2 text-slate-600 hover:text-red-600 dark:text-slate-300 dark:hover:text-red-400 transition-colors rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800"
                  title={t('header.logout')}
                >
                  <ArrowRightOnRectangleIcon className="w-5 h-5" />
                </button>
              )}
            </div>
          </div>
        </div>
      </header>

      {/* Navegación inferior móvil */}
      <nav
        className="flex items-center justify-between p-3 pb-3 bg-white/80 dark:bg-slate-900/80 backdrop-blur-sm border-t border-slate-200 dark:border-slate-700 fixed bottom-0 left-0 right-0 z-20"
        style={{ paddingBottom: 'calc(env(safe-area-inset-bottom) + 0.75rem)' }}
      >
        {/* Botón Tareas */}
        <button
          disabled={!currentHome}
          onClick={() => currentHome && onViewChange(View.DASHBOARD)}
          className={`flex-1 flex flex-col items-center py-1 text-xs font-medium ${
            currentView === View.DASHBOARD ? 'text-primary-600' : 'text-slate-600'
          } ${!currentHome ? 'opacity-50 cursor-not-allowed' : ''}`}
        >
          <ListBulletIcon className="w-6 h-6"/>
          {t('header.nav.tasks')}
        </button>

        {/* Botón Premios */}
        <button
          disabled={rewardsDisabled}
          onClick={() => !rewardsDisabled && onViewChange(View.REWARDS)}
          className={`flex-1 flex flex-col items-center py-1 text-xs font-medium ${
            currentView === View.REWARDS ? 'text-primary-600' : 'text-slate-600'
          } ${rewardsDisabled ? 'opacity-50 cursor-not-allowed' : ''}`}
          title={t('header.nav.rewards')}
        >
          <GiftIcon className="w-6 h-6"/>
          <span>{t('header.nav.rewards')}</span>
        </button>

        {/* Botón Añadir */}
        {currentHome && (
          <button
            onClick={onNewTaskClick}
            className="flex flex-col items-center -mt-6"
          >
            <div className="bg-primary-600 text-white rounded-full p-3 shadow-lg border-4 border-white dark:border-slate-900">
              <PlusIcon className="w-6 h-6"/>
            </div>
            <span className="text-xs font-medium mt-1 text-primary-600">{t('header.nav.add')}</span>
          </button>
        )}

        {/* Botón Estadísticas */}
        <button
          disabled={!currentHome}
          onClick={() => currentHome && onViewChange(View.STATS)}
          className={`flex-1 flex flex-col items-center py-1 text-xs font-medium ${
            currentView === View.STATS ? 'text-primary-600' : 'text-slate-600'
          } ${!currentHome ? 'opacity-50 cursor-not-allowed' : ''}`}
        >
          <ChartBarIcon className="w-6 h-6"/>
          {t('header.nav.stats')}
        </button>

        {/* Botón Configuración */}
        <button
          disabled={disableSettingsNavigation}
          onClick={() => !disableSettingsNavigation && onViewChange(View.SETTINGS)}
          className={`flex-1 flex flex-col items-center py-1 text-xs font-medium ${
            currentView === View.SETTINGS ? 'text-primary-600' : 'text-slate-600'
          } ${disableSettingsNavigation ? 'opacity-50 cursor-not-allowed' : ''}`}
        >
          <Cog6ToothIcon className="w-6 h-6"/>
          {t('header.nav.settings')}
        </button>
      </nav>
    </>
  );
};

export default Header;
