const parseVersion = (version: string): number[] => {
  return String(version || '0.0.0')
    .split('.')
    .map((part) => {
      const numeric = String(part).match(/\d+/)?.[0];
      return Number(numeric || 0);
    })
    .slice(0, 4);
};

export const isVersionLowerThan = (currentVersion: string, minimumVersion: string): boolean => {
  const current = parseVersion(currentVersion);
  const minimum = parseVersion(minimumVersion);
  const maxLength = Math.max(current.length, minimum.length);

  for (let i = 0; i < maxLength; i += 1) {
    const currentPart = current[i] ?? 0;
    const minimumPart = minimum[i] ?? 0;
    if (currentPart < minimumPart) return true;
    if (currentPart > minimumPart) return false;
  }

  return false;
};
