/**
 * Apple Billing Service
 * Maneja compras de suscripción en iOS a través del plugin nativo AppleBilling (StoreKit).
 */

export interface AppleBillingProduct {
  productId: string;
  title: string;
  description: string;
  price: string;
  priceAmount?: number;
  currencyCode?: string;
}

export interface AppleBillingPurchase {
  transactionId: string;
  originalTransactionId?: string;
  productId: string;
  purchaseDateMs?: number;
  expirationDateMs?: number | null;
}

export const APPLE_PRODUCTS = {
  premium_monthly_sub: 'housezen_premium_monthly_sub_ios',
  premium_yearly_sub: 'housezen_premium_yearly_sub_ios',
} as const;

interface NativeAppleBillingPlugin {
  queryProducts(options: { productIds: string[] }): Promise<{ products: AppleBillingProduct[] }>;
  purchaseSubscription(options: { productId: string }): Promise<AppleBillingPurchase>;
  restorePurchases(): Promise<{ purchases: AppleBillingPurchase[] }>;
}

const getPlugin = (): NativeAppleBillingPlugin | null => {
  if (typeof window === 'undefined') return null;
  const cap = (window as any).Capacitor;
  return (cap?.Plugins?.AppleBilling as NativeAppleBillingPlugin) || null;
};

class AppleBillingService {
  isAvailable(): boolean {
    if (typeof window === 'undefined') return false;
    const cap = (window as any).Capacitor;
    return !!cap?.isNativePlatform?.() && cap.getPlatform?.() === 'ios' && !!getPlugin();
  }

  async queryProducts(productIds: string[]): Promise<AppleBillingProduct[]> {
    if (!this.isAvailable()) {
      throw new Error('Apple Billing no está disponible en este entorno.');
    }
    const plugin = getPlugin();
    if (!plugin) throw new Error('Plugin AppleBilling no disponible.');
    const result = await plugin.queryProducts({ productIds });
    return result?.products || [];
  }

  async purchaseSubscription(productId: string): Promise<AppleBillingPurchase> {
    if (!this.isAvailable()) {
      throw new Error('Apple Billing no está disponible en este entorno.');
    }
    const plugin = getPlugin();
    if (!plugin) throw new Error('Plugin AppleBilling no disponible.');
    return plugin.purchaseSubscription({ productId });
  }

  async restorePurchases(): Promise<AppleBillingPurchase[]> {
    if (!this.isAvailable()) {
      throw new Error('Apple Billing no está disponible en este entorno.');
    }
    const plugin = getPlugin();
    if (!plugin) throw new Error('Plugin AppleBilling no disponible.');
    const result = await plugin.restorePurchases();
    return result?.purchases || [];
  }
}

export const appleBillingService = new AppleBillingService();
