import React, { useEffect, useState } from 'react';
import { AppConfig, User } from '../types';
import { useAppConfig } from '../hooks/useAppConfig';

interface AdminPortalPageProps {
  currentUser: User | null;
  onBackToApp: () => void;
  onLogout: () => Promise<void> | void;
}

const AdminPortalPage: React.FC<AdminPortalPageProps> = ({ onBackToApp, onLogout }) => {
  const { appConfig, loading, error, save, refresh } = useAppConfig();
  const [draft, setDraft] = useState<AppConfig>(appConfig);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    setDraft(appConfig);
  }, [appConfig]);

  const setNumber = (event: React.ChangeEvent<HTMLInputElement>, updater: (cfg: AppConfig, value: number) => AppConfig) => {
    const value = Number(event.target.value);
    setDraft((prev) => updater(prev, Number.isFinite(value) ? value : 0));
  };

  const setText = (event: React.ChangeEvent<HTMLInputElement>, updater: (cfg: AppConfig, value: string) => AppConfig) => {
    setDraft((prev) => updater(prev, event.target.value));
  };

  const parsePremiumBypassEmails = (raw: string): string[] => {
    return Array.from(new Set(
      raw
        .split(/[\n,;]+/)
        .map((email) => email.trim().toLowerCase())
        .filter(Boolean)
    ));
  };

  const handleSave = async () => {
    setSaving(true);
    setMessage(null);
    const result = await save(draft);
    setSaving(false);
    setMessage({
      type: result.success ? 'success' : 'error',
      text: result.success ? 'Configuración guardada correctamente.' : result.message,
    });
  };

  return (
    <div className="h-[100dvh] overflow-y-auto bg-slate-100 dark:bg-slate-900 p-4 sm:p-6">
      <div className="max-w-5xl mx-auto space-y-6 pb-6">
        <div className="bg-white dark:bg-slate-800 rounded-xl shadow-md p-5 sm:p-6 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white">Portal de Administrador</h1>
            <p className="text-sm text-slate-600 dark:text-slate-300 mt-1">Configuración global de HouseZen. Ruta: <span className="font-semibold">/admin</span></p>
          </div>
          <div className="flex gap-2">
            <button type="button" onClick={() => void refresh(true)} className="px-4 py-2 rounded-md bg-slate-200 dark:bg-slate-700 text-slate-800 dark:text-slate-100 font-semibold">Recargar</button>
            <button type="button" onClick={() => void onBackToApp()} className="px-4 py-2 rounded-md bg-primary-600 hover:bg-primary-700 text-white font-semibold">Volver a la app</button>
            <button type="button" onClick={() => void onLogout()} className="px-4 py-2 rounded-md bg-red-600 hover:bg-red-700 text-white font-semibold">Cerrar sesión</button>
          </div>
        </div>

        {message && (
          <div className={`p-4 rounded-md text-sm ${message.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
            {message.text}
          </div>
        )}

        {error && <div className="p-4 rounded-md text-sm bg-red-100 text-red-800">{error}</div>}
        {loading && <div className="p-4 rounded-md text-sm bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200">Cargando configuración...</div>}

        <div className="bg-white dark:bg-slate-800 rounded-xl shadow-md p-5 sm:p-6 space-y-4">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white">No Premium (Gratis)</h2>
          <div className="grid sm:grid-cols-2 gap-4">
            <label className="text-sm font-medium">Casas máximas (free)
              <input type="number" min={1} value={draft.limits.freeMaxHomes} onChange={(event) => setNumber(event, (cfg, value) => ({ ...cfg, limits: { ...cfg.limits, freeMaxHomes: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
            <label className="text-sm font-medium">Miembros máximos por casa (free)
              <input type="number" min={1} value={draft.limits.freeMaxMembersPerHome} onChange={(event) => setNumber(event, (cfg, value) => ({ ...cfg, limits: { ...cfg.limits, freeMaxMembersPerHome: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
            <label className="text-sm font-medium">Tareas activas máximas (free)
              <input type="number" min={1} value={draft.limits.freeMaxActiveTasks} onChange={(event) => setNumber(event, (cfg, value) => ({ ...cfg, limits: { ...cfg.limits, freeMaxActiveTasks: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
            <label className="text-sm font-medium">Plantillas periódicas (free)
              <input type="number" min={1} value={draft.limits.freeMaxPeriodicTaskTemplates} onChange={(event) => setNumber(event, (cfg, value) => ({ ...cfg, limits: { ...cfg.limits, freeMaxPeriodicTaskTemplates: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
            <label className="text-sm font-medium">Premios activos (free)
              <input type="number" min={1} value={draft.limits.freeMaxActiveRewards} onChange={(event) => setNumber(event, (cfg, value) => ({ ...cfg, limits: { ...cfg.limits, freeMaxActiveRewards: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 rounded-xl shadow-md p-5 sm:p-6 space-y-4">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white">Premium</h2>
          <div className="grid sm:grid-cols-2 gap-4">
            <label className="text-sm font-medium">Casas máximas (premium)
              <input type="number" min={1} value={draft.limits.premiumMaxHomes} onChange={(event) => setNumber(event, (cfg, value) => ({ ...cfg, limits: { ...cfg.limits, premiumMaxHomes: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
            <label className="text-sm font-medium">Premios activos (premium)
              <input type="number" min={1} value={draft.limits.premiumMaxActiveRewards} onChange={(event) => setNumber(event, (cfg, value) => ({ ...cfg, limits: { ...cfg.limits, premiumMaxActiveRewards: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
            <label className="text-sm font-medium">Precio mensual (texto)
              <input type="text" value={draft.premium.monthlyPriceLabel} onChange={(event) => setText(event, (cfg, value) => ({ ...cfg, premium: { ...cfg.premium, monthlyPriceLabel: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" placeholder="2,50EUR" />
            </label>
            <label className="text-sm font-medium">Precio anual (texto)
              <input type="text" value={draft.premium.yearlyPriceLabel} onChange={(event) => setText(event, (cfg, value) => ({ ...cfg, premium: { ...cfg.premium, yearlyPriceLabel: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" placeholder="25EUR" />
            </label>
            <label className="text-sm font-medium">Equivalencia mensual anual (texto)
              <input type="text" value={draft.premium.yearlyMonthlyEquivalentLabel} onChange={(event) => setText(event, (cfg, value) => ({ ...cfg, premium: { ...cfg.premium, yearlyMonthlyEquivalentLabel: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" placeholder="2,08EUR" />
            </label>
            <label className="text-sm font-medium flex items-center gap-2 pt-7">
              <input
                type="checkbox"
                checked={draft.premium.purchaseEnabled}
                onChange={(event) => setDraft((prev) => ({ ...prev, premium: { ...prev.premium, purchaseEnabled: event.target.checked } }))}
              />
              Habilitar botones de adquirir premium
            </label>
            <div className="text-sm font-medium sm:col-span-2">
              Habilitar compra por plataforma
              <div className="mt-2 grid sm:grid-cols-3 gap-3">
                <label className="flex items-center gap-2 text-sm font-medium">
                  <input
                    type="checkbox"
                    checked={draft.premium.purchaseEnabledByPlatform?.web ?? true}
                    onChange={(event) =>
                      setDraft((prev) => ({
                        ...prev,
                        premium: {
                          ...prev.premium,
                          purchaseEnabledByPlatform: {
                            web: event.target.checked,
                            ios: prev.premium.purchaseEnabledByPlatform?.ios ?? true,
                            android: prev.premium.purchaseEnabledByPlatform?.android ?? true,
                          },
                        },
                      }))
                    }
                  />
                  Web
                </label>
                <label className="flex items-center gap-2 text-sm font-medium">
                  <input
                    type="checkbox"
                    checked={draft.premium.purchaseEnabledByPlatform?.ios ?? true}
                    onChange={(event) =>
                      setDraft((prev) => ({
                        ...prev,
                        premium: {
                          ...prev.premium,
                          purchaseEnabledByPlatform: {
                            web: prev.premium.purchaseEnabledByPlatform?.web ?? true,
                            ios: event.target.checked,
                            android: prev.premium.purchaseEnabledByPlatform?.android ?? true,
                          },
                        },
                      }))
                    }
                  />
                  iOS
                </label>
                <label className="flex items-center gap-2 text-sm font-medium">
                  <input
                    type="checkbox"
                    checked={draft.premium.purchaseEnabledByPlatform?.android ?? true}
                    onChange={(event) =>
                      setDraft((prev) => ({
                        ...prev,
                        premium: {
                          ...prev.premium,
                          purchaseEnabledByPlatform: {
                            web: prev.premium.purchaseEnabledByPlatform?.web ?? true,
                            ios: prev.premium.purchaseEnabledByPlatform?.ios ?? true,
                            android: event.target.checked,
                          },
                        },
                      }))
                    }
                  />
                  Android
                </label>
              </div>
            </div>
            <label className="text-sm font-medium sm:col-span-2">Correos con premium gratis (sin pagar)
              <textarea
                value={(draft.premium.premiumBypassEmails || []).join('\n')}
                onChange={(event) => {
                  const emails = parsePremiumBypassEmails(event.target.value);
                  setDraft((prev) => ({ ...prev, premium: { ...prev.premium, premiumBypassEmails: emails } }));
                }}
                className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600 min-h-[100px]"
                placeholder={"email1@dominio.com\nemail2@dominio.com"}
              />
              <span className="block mt-1 text-xs text-slate-500 dark:text-slate-400">
                Puedes separarlos por línea, coma o punto y coma.
              </span>
            </label>
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 rounded-xl shadow-md p-5 sm:p-6 space-y-4">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white">Versiones y Tiendas</h2>
          <div className="grid sm:grid-cols-2 gap-4">
            <label className="text-sm font-medium">Versión mínima iOS obligatoria
              <input type="text" value={draft.minimumVersions.ios} onChange={(event) => setText(event, (cfg, value) => ({ ...cfg, minimumVersions: { ...cfg.minimumVersions, ios: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" placeholder="0.0.5" />
            </label>
            <label className="text-sm font-medium">Versión mínima Android obligatoria
              <input type="text" value={draft.minimumVersions.android} onChange={(event) => setText(event, (cfg, value) => ({ ...cfg, minimumVersions: { ...cfg.minimumVersions, android: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" placeholder="0.0.5" />
            </label>
            <label className="text-sm font-medium">URL App Store (iOS)
              <input type="text" value={draft.updateUrls.ios} onChange={(event) => setText(event, (cfg, value) => ({ ...cfg, updateUrls: { ...cfg.updateUrls, ios: value }, review: { ...cfg.review, iosUrl: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
            <label className="text-sm font-medium">URL Play Store (Android)
              <input type="text" value={draft.updateUrls.android} onChange={(event) => setText(event, (cfg, value) => ({ ...cfg, updateUrls: { ...cfg.updateUrls, android: value }, review: { ...cfg.review, androidUrl: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 rounded-xl shadow-md p-5 sm:p-6 space-y-4">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white">Popup de reseña</h2>
          <div className="grid sm:grid-cols-2 gap-4">
            <label className="text-sm font-medium flex items-center gap-2 pt-7">
              <input
                type="checkbox"
                checked={draft.review.promptEnabled}
                onChange={(event) => setDraft((prev) => ({ ...prev, review: { ...prev.review, promptEnabled: event.target.checked } }))}
              />
              Activar popup de reseña
            </label>
            <label className="text-sm font-medium">Mostrar popup tras minutos de uso
              <input type="number" min={1} value={draft.review.promptAfterMinutes} onChange={(event) => setNumber(event, (cfg, value) => ({ ...cfg, review: { ...cfg.review, promptAfterMinutes: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
            <label className="text-sm font-medium">Días de enfriamiento del popup
              <input type="number" min={0} value={draft.review.promptCooldownDays} onChange={(event) => setNumber(event, (cfg, value) => ({ ...cfg, review: { ...cfg.review, promptCooldownDays: value } }))} className="w-full mt-1 p-2 border rounded dark:bg-slate-700 dark:border-slate-600" />
            </label>
          </div>
        </div>

        <div className="sticky bottom-2 bg-white dark:bg-slate-800 rounded-xl shadow-md p-4 flex justify-end">
          <button type="button" onClick={handleSave} disabled={saving} className="px-6 py-2 rounded-md bg-emerald-600 hover:bg-emerald-700 text-white font-bold disabled:bg-emerald-300">
            {saving ? 'Guardando...' : 'Guardar configuración'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AdminPortalPage;
