// Inicialización de Firebase
import { initializeApp } from "firebase/app";
import { getAuth } from "firebase/auth";
import { getFirestore } from "firebase/firestore";
import { getStorage } from "firebase/storage";
import { getAnalytics, isSupported, Analytics } from "firebase/analytics";
import { getFunctions } from "firebase/functions";

const cleanEnvValue = (value: string | undefined): string | undefined => {
  if (!value) return undefined;
  return value.trim().replace(/^['"]|['"]$/g, "");
};

const firebaseApiKey =
  cleanEnvValue(process.env.PARCEL_FIREBASE_API_KEY_IOS) ||
  cleanEnvValue(process.env.PARCEL_FIREBASE_API_KEY);
const firebaseAppId =
  cleanEnvValue(process.env.PARCEL_FIREBASE_APP_ID_IOS) ||
  cleanEnvValue(process.env.PARCEL_FIREBASE_APP_ID);

// Your web app's Firebase configuration
// For Firebase JS SDK v7.20.0 and later, measurementId is optional
const firebaseConfig = {
  apiKey: firebaseApiKey,
  authDomain: cleanEnvValue(process.env.PARCEL_FIREBASE_AUTH_DOMAIN),
  projectId: cleanEnvValue(process.env.PARCEL_FIREBASE_PROJECT_ID),
  storageBucket: cleanEnvValue(process.env.PARCEL_FIREBASE_STORAGE_BUCKET),
  messagingSenderId: cleanEnvValue(process.env.PARCEL_FIREBASE_MESSAGING_SENDER_ID),
  appId: firebaseAppId,
  measurementId: cleanEnvValue(process.env.PARCEL_FIREBASE_MEASUREMENT_ID),
};

const missingKeys = Object.entries(firebaseConfig)
  .filter(([key, value]) => key !== "measurementId" && !value)
  .map(([key]) => key);

if (missingKeys.length > 0) {
  throw new Error(
    `Firebase config incompleta. Faltan: ${missingKeys.join(", ")}. ` +
    "Verifica variables PARCEL_FIREBASE_* en el build."
  );
}

// Initialize Firebase
const app = initializeApp(firebaseConfig);
let analytics: Analytics | null = null;

// In iOS WKWebView/TestFlight, Analytics may be unsupported or fail at startup.
// Keep app boot resilient and avoid a white screen on initialization errors.
isSupported()
  .then((supported) => {
    if (supported) {
      analytics = getAnalytics(app);
    }
  })
  .catch((error) => {
    console.warn("Firebase Analytics is not available in this environment:", error);
  });

// Get Firebase services
const auth = getAuth(app);
const db = getFirestore(app);
const storage = getStorage(app);
const functions = getFunctions(app);


export { app, auth, db, storage, analytics, functions };

