// Configuración de Stripe para houseZen

// Claves de API de Stripe
export const STRIPE_CONFIG = {
  // Clave pública para el cliente (segura para exponer en el frontend)
  publicKey: process.env.PARCEL_STRIPE_PUBLIC_KEY || '',
  
  // Precios de los planes
  prices: {
    premium_monthly: process.env.PARCEL_STRIPE_PRICE_MONTHLY || '', // ID del precio mensual desde .env
    premium_yearly: process.env.PARCEL_STRIPE_PRICE_YEARLY || '',   // ID del precio anual desde .env
  },
  
  // URLs de redirección después del pago
  redirectUrls: {
    success: '/success',  // Ruta de éxito después del pago
    cancel: '/settings',  // Ruta de cancelación
  },
};

// Función para obtener la URL base de la aplicación
export const getAppBaseUrl = () => {
  // En producción, usar la URL configurada en las variables de entorno
  if (process.env.NODE_ENV === 'production') {
    return process.env.APP_URL || 'https://houseZen.app';
  }
  
  // En desarrollo, usar localhost
  return 'http://localhost:1234';
};

// Función para construir las URLs completas de redirección
export const getRedirectUrls = () => {
  const baseUrl = getAppBaseUrl();
  
  return {
    success: `${baseUrl}${STRIPE_CONFIG.redirectUrls.success}`,
    cancel: `${baseUrl}${STRIPE_CONFIG.redirectUrls.cancel}`,
  };
};