import React from 'react';
import Modal from './Modal';

interface DeleteTaskConfirmationProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirmDelete: (deleteAll: boolean) => void;
  isPeriodic: boolean;
}

const DeleteTaskConfirmation: React.FC<DeleteTaskConfirmationProps> = ({
  isOpen,
  onClose,
  onConfirmDelete,
  isPeriodic
}) => {
  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <div className="p-6">
        <h3 className="text-xl font-semibold mb-4 dark:text-white">
          Confirmar eliminación
        </h3>
        <p className="mb-6 dark:text-gray-300">
          {isPeriodic
            ? "¿Deseas eliminar esta tarea y todas sus repeticiones futuras?"
            : "¿Estás seguro de que deseas eliminar esta tarea?"}
        </p>
        <div className="flex justify-end space-x-3">
          <button
            onClick={onClose}
            className="px-4 py-2 border border-gray-300 rounded-md text-gray-700 hover:bg-gray-100 dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-700"
          >
            Cancelar
          </button>
          <button
            onClick={() => onConfirmDelete(false)}
            className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700"
          >
            {isPeriodic ? "Eliminar solo esta" : "Eliminar"}
          </button>
          {isPeriodic && (
            <button
              onClick={() => onConfirmDelete(true)}
              className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700"
            >
              Eliminar todas las futuras
            </button>
          )}
        </div>
      </div>
    </Modal>
  );
};

export default DeleteTaskConfirmation;