import { User, Task, Home, Reward } from '../types';
import { notificationService } from './notificationService';
import { Timestamp } from 'firebase/firestore';

interface UserBehaviorMetrics {
  userId: string;
  totalTasks: number;
  completedTasks: number;
  periodicTasks: number;
  homesCreated: number;
  membersInvited: number;
  rewardsCreated: number;
  loginStreak: number;
  lastActiveDate: Date;
  featureUsageScore: number;
  limitHitCount: number;
  premiumFeatureAttempts: number;
}

interface PromotionTrigger {
  type: 'limit_hit' | 'feature_usage' | 'engagement' | 'time_based';
  priority: 'high' | 'medium' | 'low';
  message: string;
  actionUrl: string;
}

export class UserAnalyticsService {
  private static instance: UserAnalyticsService;
  private behaviorCache = new Map<string, UserBehaviorMetrics>();

  static getInstance(): UserAnalyticsService {
    if (!UserAnalyticsService.instance) {
      UserAnalyticsService.instance = new UserAnalyticsService();
    }
    return UserAnalyticsService.instance;
  }

  // Calcular métricas de comportamiento del usuario
  calculateUserMetrics(
    user: User,
    tasks: Task[],
    homes: Home[],
    rewards: Reward[]
  ): UserBehaviorMetrics {
    const userTasks = tasks.filter(t => t.assignedTo === user.id);
    const userHomes = homes.filter(h => h.createdBy === user.id);
    const userRewards = rewards.filter(r => r.createdBy === user.id);
    
    const completedTasks = userTasks.filter(t => t.status === 'completed').length;
    const periodicTasks = userTasks.filter(t => t.periodicity !== 'none').length;
    
    // Calcular puntuación de uso de funciones (0-100)
    let featureUsageScore = 0;
    if (userTasks.length > 0) featureUsageScore += 20;
    if (completedTasks > 5) featureUsageScore += 15;
    if (periodicTasks > 0) featureUsageScore += 20;
    if (userHomes.length > 0) featureUsageScore += 15;
    if (userRewards.length > 0) featureUsageScore += 15;
    if (homes.some(h => h.memberIds.includes(user.id) && h.memberIds.length > 2)) featureUsageScore += 15;

    const metrics: UserBehaviorMetrics = {
      userId: user.id,
      totalTasks: userTasks.length,
      completedTasks,
      periodicTasks,
      homesCreated: userHomes.length,
      membersInvited: homes.reduce((acc, h) => acc + (h.createdBy === user.id ? h.memberIds.length - 1 : 0), 0),
      rewardsCreated: userRewards.length,
      loginStreak: 0, // Se calculará desde las configuraciones de notificación
      lastActiveDate: new Date(),
      featureUsageScore,
      limitHitCount: 0, // Se incrementará cuando se detecten límites
      premiumFeatureAttempts: 0
    };

    this.behaviorCache.set(user.id, metrics);
    return metrics;
  }

  // Detectar triggers de promoción inteligente
  async detectPromotionTriggers(
    user: User,
    metrics: UserBehaviorMetrics
  ): Promise<PromotionTrigger[]> {
    if (user.plan === 'premium') return [];

    const triggers: PromotionTrigger[] = [];
    const settings = await notificationService.getNotificationSettings(user.id);
    
    if (!settings?.premiumPromotionEnabled) return [];

    // Trigger 1: Usuario activo que ha alcanzado límites múltiples veces
    if (metrics.featureUsageScore >= 60 && metrics.limitHitCount >= 3) {
      triggers.push({
        type: 'limit_hit',
        priority: 'high',
        message: '¡Veo que estás usando HouseZen intensivamente! 🚀 Desbloquea todo el potencial con Premium.',
        actionUrl: '/premium?trigger=power_user'
      });
    }

    // Trigger 2: Usuario con muchas tareas pero limitado en funciones
    if (metrics.totalTasks >= 15 && metrics.periodicTasks >= 2) {
      triggers.push({
        type: 'feature_usage',
        priority: 'high',
        message: '¡Eres súper organizado! 📋 Con Premium puedes crear tareas periódicas ilimitadas.',
        actionUrl: '/premium?trigger=task_master'
      });
    }

    // Trigger 3: Usuario social que invita miembros
    if (metrics.membersInvited >= 2 && metrics.homesCreated >= 1) {
      triggers.push({
        type: 'feature_usage',
        priority: 'medium',
        message: '¡Te encanta colaborar! 👥 Premium te permite gestionar hasta 2 casas y más miembros.',
        actionUrl: '/premium?trigger=social_user'
      });
    }

    // Trigger 4: Usuario comprometido con racha de login
    if (settings && settings.loginCount >= 7) {
      const daysSinceLastPromotion = settings.lastPremiumPromotionShown 
        ? Math.floor((Date.now() - settings.lastPremiumPromotionShown.toDate().getTime()) / (1000 * 60 * 60 * 24))
        : 999;
      
      if (daysSinceLastPromotion >= 14) {
        triggers.push({
          type: 'engagement',
          priority: 'medium',
          message: '¡Llevas una semana genial usando HouseZen! 🎉 ¿Qué tal si pruebas Premium?',
          actionUrl: '/premium?trigger=loyal_user'
        });
      }
    }

    // Trigger 5: Usuario que usa recompensas
    if (metrics.rewardsCreated >= 1 && metrics.completedTasks >= 10) {
      triggers.push({
        type: 'feature_usage',
        priority: 'medium',
        message: '¡Motivar con recompensas es genial! 🏆 Premium te permite crear hasta 25 recompensas por casa.',
        actionUrl: '/premium?trigger=reward_creator'
      });
    }

    // Ordenar por prioridad
    return triggers.sort((a, b) => {
      const priorityOrder = { high: 3, medium: 2, low: 1 };
      return priorityOrder[b.priority] - priorityOrder[a.priority];
    });
  }

  // Registrar intento de función premium
  recordPremiumFeatureAttempt(userId: string, feature: string): void {
    const metrics = this.behaviorCache.get(userId);
    if (metrics) {
      metrics.premiumFeatureAttempts++;
      this.behaviorCache.set(userId, metrics);
    }
  }

  // Registrar límite alcanzado
  recordLimitHit(userId: string, limitType: string): void {
    const metrics = this.behaviorCache.get(userId);
    if (metrics) {
      metrics.limitHitCount++;
      this.behaviorCache.set(userId, metrics);
    }
  }

  // Enviar promoción inteligente
  async sendIntelligentPromotion(
    user: User,
    tasks: Task[],
    homes: Home[],
    rewards: Reward[]
  ): Promise<boolean> {
    try {
      const metrics = this.calculateUserMetrics(user, tasks, homes, rewards);
      const triggers = await this.detectPromotionTriggers(user, metrics);
      
      if (triggers.length === 0) return false;

      // Usar el trigger de mayor prioridad
      const bestTrigger = triggers[0];
      
      await notificationService.sendNotification({
        userId: user.id,
        type: 'premium_promotion',
        title: '✨ HouseZen Premium',
        message: bestTrigger.message,
        read: false,
        metadata: {
          actionUrl: bestTrigger.actionUrl,
          triggerType: bestTrigger.type,
          priority: bestTrigger.priority
        }
      });

      // Actualizar configuraciones para registrar que se mostró la promoción
      const settings = await notificationService.getNotificationSettings(user.id);
      if (settings) {
        await notificationService.updateNotificationSettings({
          ...settings,
          lastPremiumPromotionShown: Timestamp.now()
        });
      }

      return true;
    } catch (error) {
      console.error('Error sending intelligent promotion:', error);
      return false;
    }
  }

  // Verificar si debe mostrar promoción inteligente
  async shouldShowIntelligentPromotion(
    user: User,
    tasks: Task[],
    homes: Home[],
    rewards: Reward[]
  ): Promise<boolean> {
    if (user.plan === 'premium') return false;
    
    const settings = await notificationService.getNotificationSettings(user.id);
    if (!settings?.premiumPromotionEnabled) return false;

    // No mostrar si se mostró en las últimas 2 semanas (más frecuente que el sistema básico)
    if (settings.lastPremiumPromotionShown) {
      const twoWeeksAgo = new Date();
      twoWeeksAgo.setDate(twoWeeksAgo.getDate() - 14);
      
      if (settings.lastPremiumPromotionShown.toDate() > twoWeeksAgo) {
        return false;
      }
    }

    const metrics = this.calculateUserMetrics(user, tasks, homes, rewards);
    const triggers = await this.detectPromotionTriggers(user, metrics);
    
    // Mostrar si hay triggers de alta prioridad o múltiples triggers
    return triggers.some(t => t.priority === 'high') || triggers.length >= 2;
  }
}

export const userAnalyticsService = UserAnalyticsService.getInstance();
