import React from 'react';
import { Task, User, TaskStatus, Periodicity } from '../types';
import { useI18n } from '../i18n/I18nProvider';

const addDays = (date: Date, days: number): Date => {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
};

interface TaskItemProps {
  task: Task;
  users: User[];
  onEdit: () => void;
  onDelete: () => Promise<void>;
  onComplete: () => Promise<void>;
  onUpdateStatus: (newStatus: TaskStatus) => Promise<void>;
  onDragStart: (e: React.DragEvent<HTMLDivElement>) => void;
  onTaskClick: (task: Task) => void;
  // Funciones específicas para tareas periódicas
  onUpdatePeriodicTaskDayStatus?: (taskId: string, dayIndex: number, status: TaskStatus, selectedDate?: Date) => Promise<void>;
  getPeriodicTaskDayInfo?: (task: Task, dayIndex: number) => { status: TaskStatus; assignedTo: string | null };
}

const TaskItem: React.FC<TaskItemProps> = ({
  task,
  users,
  onEdit,
  onDelete,
  onComplete,
  onUpdateStatus,
  onDragStart,
  onTaskClick,
  onUpdatePeriodicTaskDayStatus,
  getPeriodicTaskDayInfo,
}) => {
  const { t } = useI18n();
  const getPeriodicIntervalDays = (): number => {
    switch (task.periodicity) {
      case Periodicity.WEEKLY:
        return 7;
      case Periodicity.MONTHLY:
        return 30;
      case Periodicity.CUSTOM_DAYS:
        return Math.max(1, task.customDays || 1);
      case Periodicity.DAILY:
      default:
        return 1;
    }
  };

  const normalizeDate = (date: Date): Date => {
    const normalized = new Date(date);
    normalized.setHours(0, 0, 0, 0);
    return normalized;
  };

  const resolvePeriodicOccurrenceDate = (dayKey: string, dayInfo: any): Date | null => {
    if (dayInfo?.date) {
      const parsedDate = new Date(dayInfo.date);
      if (!isNaN(parsedDate.getTime())) {
        return parsedDate;
      }
    }

    const startDate = new Date(task.fechaInicio || task.dueDate);
    if (isNaN(startDate.getTime())) {
      return null;
    }

    if (typeof dayInfo?.day === 'number') {
      return addDays(new Date(startDate), dayInfo.day);
    }

    const parsedDayKey = Number.parseInt(dayKey, 10);
    if (!Number.isNaN(parsedDayKey)) {
      const intervalDays = getPeriodicIntervalDays();
      return addDays(new Date(startDate), parsedDayKey * intervalDays);
    }

    return null;
  };

  // Para tareas periódicas, obtener asignación desde registroDetallado usando la fecha correcta
  const getAssignedUser = () => {
    if (task.periodicity !== Periodicity.NONE && task.registroDetallado) {
      const taskDate = normalizeDate(new Date(task.dueDate));
      
      // Buscar en registroDetallado el día que coincida con la fecha
      for (const [dayKey, dayInfo] of Object.entries(task.registroDetallado)) {
        const occurrenceDate = resolvePeriodicOccurrenceDate(dayKey, dayInfo);
        if (!occurrenceDate) continue;

        if (normalizeDate(occurrenceDate).getTime() === taskDate.getTime() && dayInfo.assignedTo) {
          return users.find(u => u.id === dayInfo.assignedTo) || null;
        }
      }
    }
    
    // Para tareas no periódicas, usar assignedTo del task expandido
    return task.assignedTo ? users.find(u => u.id === task.assignedTo) : null;
  };
  
  const assignedUser = getAssignedUser();

  // Calcular dayIndex para tareas periódicas
  const getDayIndex = () => {
    if (task.periodicity === Periodicity.NONE || !task.fechaInicio) {
      return null;
    }
    
    // Para tareas periódicas con registroDetallado, buscar la clave por fecha
    if (task.registroDetallado && Object.keys(task.registroDetallado).length > 0) {
      const targetDate = normalizeDate(new Date(task.dueDate));

      for (const [dayKey, dayInfo] of Object.entries(task.registroDetallado)) {
        const occurrenceDate = resolvePeriodicOccurrenceDate(dayKey, dayInfo);
        if (!occurrenceDate) continue;

        const normalizedOccurrenceDate = normalizeDate(occurrenceDate);
        if (normalizedOccurrenceDate.getTime() === targetDate.getTime()) {
          return Number.parseInt(dayKey, 10);
        }
      }
    }
    
    // Fallback: calcular como diferencia de días
    const taskDate = new Date(task.dueDate);
    const startDate = new Date(task.fechaInicio);
    taskDate.setHours(0, 0, 0, 0);
    startDate.setHours(0, 0, 0, 0);
    
    const diffTime = taskDate.getTime() - startDate.getTime();
    return Math.floor(diffTime / (1000 * 60 * 60 * 24));
  };

  const dayIndex = getDayIndex();
  const isPeriodicTask = task.periodicity !== Periodicity.NONE && dayIndex !== null;

  // Funciones para manejar cambios de estado
  const handleUpdateStatus = async (newStatus: TaskStatus) => {
    if (isPeriodicTask && onUpdatePeriodicTaskDayStatus) {
      // Pasar la fecha de la tarea correcta (que ya está calculada en task.dueDate)
      await onUpdatePeriodicTaskDayStatus(task.id, dayIndex!, newStatus, new Date(task.dueDate));
    } else {
      await onUpdateStatus(newStatus);
    }
  };

  const handleComplete = async () => {
    if (isPeriodicTask && onUpdatePeriodicTaskDayStatus) {
      // Pasar la fecha de la tarea correcta (que ya está calculada en task.dueDate)
      await onUpdatePeriodicTaskDayStatus(task.id, dayIndex!, TaskStatus.COMPLETED, new Date(task.dueDate));
    } else {
      await onComplete();
    }
  };

  const getStatusButton = () => {
    switch (task.status) {
      case TaskStatus.PENDING:
        return <button 
          onClick={(e) => { 
            e.stopPropagation(); 
            handleUpdateStatus(TaskStatus.IN_PROGRESS); 
          }} 
          className="flex-1 bg-blue-500 hover:bg-blue-600 text-white text-xs font-bold py-1 px-2 rounded-md transition-colors"
        >
          {t('task.action.start')}
        </button>;
      case TaskStatus.IN_PROGRESS:
        return <button 
          onClick={(e) => { 
            e.stopPropagation(); 
            handleComplete(); 
          }} 
          className="flex-1 bg-green-500 hover:bg-green-600 text-white text-xs font-bold py-1 px-2 rounded-md transition-colors"
        >
          {t('task.action.complete')}
        </button>;
      case TaskStatus.NOT_DONE:
        return <button 
          onClick={(e) => { 
            e.stopPropagation(); 
            handleUpdateStatus(TaskStatus.PENDING); 
          }} 
          className="flex-1 bg-gray-500 hover:bg-gray-600 text-white text-xs font-bold py-1 px-2 rounded-md transition-colors"
        >
          {t('task.action.reactivate')}
        </button>;
      case TaskStatus.COMPLETED:
        return <button 
          onClick={(e) => { 
            e.stopPropagation(); 
            handleUpdateStatus(TaskStatus.IN_PROGRESS); 
          }} 
          className="flex-1 bg-purple-500 hover:bg-purple-600 text-white text-xs font-bold py-1 px-2 rounded-md transition-colors"
        >
          {t('task.action.reopen')}
        </button>;
      default:
        return null;
    }
  };

  const getBackButton = () => {
    switch (task.status) {
      case TaskStatus.PENDING:
        return <button onClick={(e) => { e.stopPropagation(); handleUpdateStatus(TaskStatus.NOT_DONE); }} className="flex-1 bg-red-500 hover:bg-red-600 text-white text-xs font-bold py-1 px-2 rounded-md transition-colors">{t('task.action.reject')}</button>;
      case TaskStatus.IN_PROGRESS:
        return <button onClick={(e) => { e.stopPropagation(); handleUpdateStatus(TaskStatus.PENDING); }} className="flex-1 bg-yellow-500 hover:bg-yellow-600 text-white text-xs font-bold py-1 px-2 rounded-md transition-colors">{t('task.status.pending')}</button>;
      case TaskStatus.COMPLETED:
        return <button onClick={(e) => { e.stopPropagation(); handleUpdateStatus(TaskStatus.NOT_DONE); }} className="flex-1 bg-red-500 hover:bg-red-600 text-white text-xs font-bold py-1 px-2 rounded-md transition-colors">{t('task.action.reject')}</button>;
      case TaskStatus.NOT_DONE:
        return <button onClick={(e) => { e.stopPropagation(); handleUpdateStatus(TaskStatus.IN_PROGRESS); }} className="flex-1 bg-blue-500 hover:bg-blue-600 text-white text-xs font-bold py-1 px-2 rounded-md transition-colors">{t('task.action.start')}</button>;
      default:
        return null;
    }
  };

  return (
    <div 
        draggable={true}
        onDragStart={onDragStart}
        className={`bg-white dark:bg-slate-900/70 p-2 rounded-lg shadow-sm border-l-4 transition-all duration-200 hover:scale-[1.03] transform-gpu cursor-grab active:cursor-grabbing active:opacity-50 overflow-hidden`}
        style={{ borderColor: assignedUser ? assignedUser.color : '#9ca3af' }}
        onClick={(e) => {
          // Only open details if it's a direct click on the task, not when changing status
          if (e.target === e.currentTarget || e.target.tagName !== 'BUTTON') {
            onTaskClick(task);
          }
        }}
    >
      {/* Cabecera de la tarea con nombre de la persona asignada al mismo nivel - Optimizado */}
      <div className="flex justify-between items-center mb-2">
        <div className="flex items-center gap-1 max-w-[65%] sm:max-w-[75%]">
          <span className="text-lg sm:text-xl flex-shrink-0">{task.emoji}</span>
          <div className="w-full">
            <h3 className="font-bold text-slate-800 dark:text-slate-100 text-xs sm:text-sm truncate">{task.title}</h3>
          </div>
        </div>
        <div className="flex items-center gap-1 ml-1 flex-shrink-0">
          {assignedUser && (
            <div className="flex items-center gap-1">
              {/* Avatar oculto pero mantenido en el DOM */}
              <img src={assignedUser.avatar} alt={assignedUser.name} className="hidden" />
              <span className="text-xs text-slate-500 dark:text-slate-400 truncate max-w-[40px] sm:max-w-[60px]">{assignedUser.name}</span>
            </div>
          )}
          <span className="flex-shrink-0 bg-yellow-400 text-yellow-900 text-xs font-bold px-1 py-0.5 rounded-full">{task.points} pts</span>
        </div>
      </div>

      {/* Botones de acción - Optimizados */}
      <div className="flex flex-col gap-1">
        <div className="flex gap-1 w-full">
          <div className="flex-1">
            {getStatusButton()}
          </div>
          <div className="flex-1">
            {getBackButton()}
          </div>
          <button 
            onClick={(e) => { e.stopPropagation(); onEdit(); }} 
            className="w-8 h-7 bg-blue-100 hover:bg-blue-200 text-blue-700 text-xs font-medium rounded-md transition-colors flex items-center justify-center"
            aria-label="Editar"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
            </svg>
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onDelete(); }} 
            className="w-8 h-7 bg-red-100 hover:bg-red-200 text-red-700 text-xs font-medium rounded-md transition-colors flex items-center justify-center"
            aria-label="Eliminar"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default TaskItem;
