    async createHome(name: string, creator: AppUser): Promise<void> {
        const userHomes = await this.getHomesForUser(creator.id);
        const maxHomes = creator.plan === 'premium' ? 2 : 1;
        if (userHomes.length >= maxHomes) {
            // Registrar que el usuario alcanzó el límite
            await notificationService.recordLimitHit(creator.id, 'homes');
            throw new Error(
                creator.plan === 'premium'
                    ? 'El plan premium permite hasta 2 casas por cuenta.'
                    : 'El plan gratuito permite 1 casa. Mejora a Premium para gestionar hasta 2 casas.'
            );
        }

        const newHomeRef = doc(collection(db, 'homes'));
        const newHome: Omit<Home, 'id'> = { name, adminIds: [creator.id], memberIds: [creator.id] };
        await setDoc(newHomeRef, newHome);
        
        // Registrar actividad del usuario para analytics
        try {
            await notificationService.recordPremiumFeatureAttempt(creator.id, 'create_home');
        } catch (error) {
            console.error('Error al registrar actividad de analytics:', error);
        }
    }
    
