    // Actualiza la asignación de un día específico de una tarea periódica
    async updatePeriodicTaskDayAssignment(
        taskId: string,
        dayIndex: number,
        assignedTo: string | null,
        selectedDate: Date
    ): Promise<void> {
        try {
            if (!selectedDate) throw new Error('Debe proporcionarse selectedDate');

            console.log('🔧 updatePeriodicTaskDayAssignment llamado con:', { taskId, dayIndex, assignedTo, selectedDate });

            const taskRef = doc(db, 'tasks', taskId);
            const taskSnap = await getDoc(taskRef);

            if (!taskSnap.exists()) {
                throw new Error('Tarea no encontrada');
            }

            const task = taskSnap.data() as Task;

            if (task.periodicity === Periodicity.NONE) {
                throw new Error('Esta función solo es para tareas periódicas');
            }

            if (!task.registroDetallado || Object.keys(task.registroDetallado).length === 0) {
                throw new Error('Tarea periódica sin registroDetallado válido');
            }

            console.log('📊 registroDetallado actual:', task.registroDetallado);

            // Normalizar selectedDate
            const refDate = new Date(selectedDate);
            refDate.setHours(0, 0, 0, 0);

            // Buscar la clave de registroDetallado que coincide con la fecha
            const dayKey = Object.keys(task.registroDetallado).find(key => {
                const item = task.registroDetallado[key];
                if (!item) return false;

                const dayDate = item.date
                    ? new Date(item.date)
                    : task.fechaInicio
                        ? addDays(new Date(task.fechaInicio), parseInt(key))
                        : null;

                if (!dayDate) return false;

                dayDate.setHours(0, 0, 0, 0);
                return dayDate.getTime() === refDate.getTime();
            });

            if (!dayKey) {
                throw new Error('No se encontró el día específico para actualizar');
            }

            const prevAssignedTo = task.registroDetallado[dayKey].assignedTo;

            // Actualizar solo el assignedTo del día específico en Firestore
            await updateDoc(taskRef, {
                [`registroDetallado.${dayKey}.assignedTo`]: assignedTo
            });

            console.log(`✅ Asignación actualizada: ${prevAssignedTo} → ${assignedTo} para dayKey ${dayKey}`);

        } catch (error) {
            console.error('❌ Error al actualizar asignación del día:', error);
            throw error;
        }
    }

    // Nueva función para obtener el estado y asignación de un día específico
    getPeriodicTaskDayInfo(task: Task, dayIndex: number): { status: TaskStatus; assignedTo: string | null } {
        // Primero intentar con el nuevo sistema
        if (task.registroDetallado) {
            const dayKey = dayIndex.toString();
            const dayInfo = task.registroDetallado[dayKey];
            if (dayInfo) {
                return {
                    status: dayInfo.status as TaskStatus,
                    assignedTo: dayInfo.assignedTo || null
                };
            }
        }
        
        // Fallback al sistema legacy
        if (task.registro && dayIndex >= 0 && dayIndex < task.registro.length) {
            const statusChar = task.registro[dayIndex];
            let status: TaskStatus;
            
            switch (statusChar) {
                case '2':
                    status = TaskStatus.COMPLETED;
                    break;
                case '1':
                    status = TaskStatus.IN_PROGRESS;
                    break;
                case '3':
                    status = TaskStatus.NOT_DONE;
                    break;
                case '4':
                    status = TaskStatus.NOT_DONE; // Eliminado se trata como no realizada
                    break;
                default:
                    status = TaskStatus.PENDING;
            }
            
            return {
                status: status,
                assignedTo: task.assignedTo || null // Asignación por defecto
            };
        }
        
        // Default
        return {
            status: TaskStatus.PENDING,
            assignedTo: task.assignedTo || null
        };
    }
    
