    async claimReward(rewardId: string, userId: string): Promise<{ success: boolean; message: string }> {
        if (!auth.currentUser) return { success: false, message: 'Usuario no autenticado' };
        
        try {
            // Obtener información del premio
            const rewardRef = doc(db, 'rewards', rewardId);
            const rewardSnap = await getDoc(rewardRef);
            
            if (!rewardSnap.exists()) {
                return { success: false, message: 'Premio no encontrado' };
            }
            
            const reward = { id: rewardSnap.id, ...rewardSnap.data() } as Reward;
            
            if (!reward.isActive) {
                return { success: false, message: 'Este premio ya no está disponible' };
            }
            
            // Verificar puntos del usuario en este hogar
            const userPoints = await this.getUserPointsInHome(userId, reward.homeId);
            
            if (userPoints < reward.pointsCost) {
                return { success: false, message: `Necesitas ${reward.pointsCost} puntos. Tienes ${userPoints} puntos.` };
            }
            
            // Crear la solicitud de canje
            const newClaim: Omit<RewardClaim, 'id'> = {
                rewardId,
                userId,
                homeId: reward.homeId,
                pointsSpent: reward.pointsCost,
                status: RewardStatus.PENDING,
                claimedAt: new Date().toISOString()
            };
            
            await addDoc(collection(db, 'rewardClaims'), newClaim);
            
            // Notificar a los administradores del hogar
            try {
                const homeRef = doc(db, 'homes', reward.homeId);
                const homeSnap = await getDoc(homeRef);
                
                if (homeSnap.exists()) {
                    const home = { id: homeSnap.id, ...homeSnap.data() } as Home;
                    const userRef = doc(db, 'users', userId);
                    const userSnap = await getDoc(userRef);
                    
                    if (userSnap.exists()) {
                        const user = { id: userSnap.id, ...userSnap.data() } as AppUser;
                        
                        // Notificar a todos los administradores
                        for (const adminId of home.adminIds) {
                            if (adminId !== userId) { // No notificar al mismo usuario
                                await notificationService.sendRewardRequestNotification(
                                    adminId,
                                    user.name,
                                    reward.title,
                                    rewardId,
                                    home.name
                                );
                            }
                        }
                    }
                }
            } catch (error) {
                console.error('Error al enviar notificación de solicitud de premio:', error);
            }
            
            return { success: true, message: 'Premio solicitado correctamente. Espera a que un administrador lo procese.' };
        } catch (error) {
            console.error('Error al canjear premio:', error);
            return { success: false, message: 'Error al procesar la solicitud' };
        }
    }

