    async getUserPointsInHome(userId: string, homeId: string): Promise<number> {
        // Obtener todas las tareas del hogar
        const tasksQuery = query(
            collection(db, 'tasks'),
            where('homeId', '==', homeId)
        );
        
        const tasksSnap = await getDocs(tasksQuery);
        let totalPoints = 0;
        
        tasksSnap.forEach(doc => {
            const task = doc.data() as Task;
            
            // Puntos de tareas no periódicas completadas por el usuario
            if (task.status === TaskStatus.COMPLETED && task.completedBy === userId) {
                totalPoints += task.points;
            }
            
            // Puntos de días completados en tareas periódicas
            if (task.registroDetallado) {
                Object.values(task.registroDetallado).forEach(dayRecord => {
                    if (dayRecord.completedBy === userId && dayRecord.status === TaskStatus.COMPLETED) {
                        totalPoints += task.points;
                    }
                });
            }
            // Soporte para formato legacy (registro string)
            else if (task.registro && task.completedBy === userId) {
                const completedDays = task.registro.split('').filter(day => day === '2').length;
                totalPoints += completedDays * task.points;
            }
        });
        
        // Restar puntos gastados en premios
        const claimsQuery = query(
            collection(db, 'rewardClaims'),
            where('homeId', '==', homeId),
            where('userId', '==', userId),
            where('status', '==', RewardStatus.GRANTED)
        );
        
        const claimsSnap = await getDocs(claimsQuery);
        let spentPoints = 0;
        
        claimsSnap.forEach(doc => {
            const claim = doc.data() as RewardClaim;
            spentPoints += claim.pointsSpent;
        });
        
        return totalPoints - spentPoints;
    }

