import React from 'react';
import { Task, User, TaskStatus, Periodicity } from '../types';
import Modal from './Modal';
import PeriodicTaskDayManager from './PeriodicTaskDayManager';
import { useI18n } from '../i18n/I18nProvider';

const addDays = (date: Date, days: number): Date => {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
};

interface TaskDetailProps {
  task: Task | null;
  users: User[];
  isOpen: boolean;
  onClose: () => void;
  onUpdatePeriodicTaskDayAssignment?: (taskId: string, dayIndex: number, assignedTo: string | null, selectedDate?: Date) => Promise<void>;
  onUpdatePeriodicTaskDayStatus?: (taskId: string, dayIndex: number, status: TaskStatus, selectedDate?: Date) => Promise<void>;
  getPeriodicTaskDayInfo?: (task: Task, dayIndex: number) => { status: TaskStatus; assignedTo: string | null };
}

// Función de formateo de fecha en formato dd/mm/yyyy
const formatDateEs = (date: Date) => {
  return date.toLocaleDateString('es-ES', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
};

const isPastDate = (date: Date) => {
  const now = new Date();
  return date.getTime() < now.getTime();
};

const TaskDetail: React.FC<TaskDetailProps> = ({ 
  task, 
  users, 
  isOpen, 
  onClose, 
  onUpdatePeriodicTaskDayAssignment, 
  onUpdatePeriodicTaskDayStatus, 
  getPeriodicTaskDayInfo 
}) => {
  const { t } = useI18n();
  if (!task) return null;
  
  const completedByUser = task.completedBy ? users.find(u => u.id === task.completedBy) : null;
  const assignedUser = task.assignedTo ? users.find(u => u.id === task.assignedTo) : null;
  const isOverdue = isPastDate(new Date(task.dueDate)) && task.status !== TaskStatus.COMPLETED;
  const getPeriodicDayDate = (dayIndex: number): Date => {
    const dayRecord = task.registroDetallado?.[dayIndex.toString()];
    if (dayRecord?.date) {
      const parsedDate = new Date(dayRecord.date);
      if (!isNaN(parsedDate.getTime())) {
        return parsedDate;
      }
    }

    const startDate = new Date(task.fechaInicio || task.dueDate);
    const dayOffset = typeof dayRecord?.day === 'number' ? dayRecord.day : dayIndex;
    return addDays(startDate, dayOffset);
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <div className="p-5">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <span className="text-3xl">{task.emoji}</span>
            <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100">{task.title}</h2>
          </div>
          <span className="bg-yellow-400 text-yellow-900 text-sm font-bold px-3 py-1 rounded-full">
            {task.points} pts
          </span>
        </div>
        
        <div className="mb-4 bg-slate-100 dark:bg-slate-700/30 p-3 rounded-lg">
          <p className="text-slate-700 dark:text-slate-300 whitespace-pre-line">{task.description}</p>
        </div>
        
        <div className="space-y-3 text-sm">
          <div className="flex justify-between items-center p-2 border-b border-slate-200 dark:border-slate-700">
            <span className="font-medium text-slate-500 dark:text-slate-400">Estado:</span>
            <span className={`font-semibold px-2 py-1 rounded-full ${task.status === TaskStatus.COMPLETED ? 'bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300' : 
              task.status === TaskStatus.IN_PROGRESS ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-300' : 
              task.status === TaskStatus.NOT_DONE ? 'bg-gray-100 dark:bg-gray-700/30 text-gray-800 dark:text-gray-300' : 
              'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-300'}`}>
              {task.status === TaskStatus.PENDING
                ? t('task.status.pending')
                : task.status === TaskStatus.IN_PROGRESS
                  ? t('task.status.inProgress')
                  : task.status === TaskStatus.NOT_DONE
                    ? t('task.status.notDone')
                    : t('task.status.completed')}
            </span>
          </div>
          
          <div className="flex justify-between items-center p-2 border-b border-slate-200 dark:border-slate-700">
            <span className="font-medium text-slate-500 dark:text-slate-400">{t('taskForm.field.dueDate')}:</span>
            <span className={`font-semibold ${isOverdue ? 'text-red-500' : 'text-slate-700 dark:text-slate-300'}`}>
              {formatDateEs(new Date(task.dueDate))}
            </span>
          </div>
          
          <div className="flex justify-between items-center p-2 border-b border-slate-200 dark:border-slate-700">
            <span className="font-medium text-slate-500 dark:text-slate-400">{t('taskForm.field.periodicity')}:</span>
            <span className="font-semibold text-slate-700 dark:text-slate-300">{task.periodicity}</span>
          </div>
          
          {task.periodicity !== Periodicity.NONE && (task.fechaFin || task.endDate) && (
            <div className="flex justify-between items-center p-2 border-b border-slate-200 dark:border-slate-700">
              <span className="font-medium text-slate-500 dark:text-slate-400">{t('taskForm.field.repeatUntil')}:</span>
              <span className="font-semibold text-slate-700 dark:text-slate-300">
                {formatDateEs(new Date(task.fechaFin || task.endDate!))}
              </span>
            </div>
          )}
          
          {assignedUser && (
            <div className="flex justify-between items-center p-2 border-b border-slate-200 dark:border-slate-700">
              <span className="font-medium text-slate-500 dark:text-slate-400">{t('taskForm.field.assignTo')}:</span>
              <div className="flex items-center">
                {/* Avatar oculto pero mantenido en el DOM */}
                <img src={assignedUser.avatar} alt={assignedUser.name} className="hidden" />
                <span className="font-semibold text-slate-700 dark:text-slate-300">{assignedUser.name}</span>
              </div>
            </div>
          )}
          
          {task.status === TaskStatus.COMPLETED && completedByUser && (
            <div className="flex justify-between items-center p-2 border-b border-slate-200 dark:border-slate-700">
              <span className="font-medium text-slate-500 dark:text-slate-400">{t('taskDetail.completedBy')}:</span>
              <div className="flex items-center">
                {/* Avatar oculto pero mantenido en el DOM */}
                <img src={completedByUser.avatar} alt={completedByUser.name} className="hidden" />
                <span className="font-semibold text-slate-700 dark:text-slate-300">{completedByUser.name}</span>
              </div>
            </div>
          )}
          
          {task.completedAt && task.status === TaskStatus.COMPLETED && (
            <div className="flex justify-between items-center p-2 border-b border-slate-200 dark:border-slate-700">
              <span className="font-medium text-slate-500 dark:text-slate-400">{t('taskDetail.completedAt')}:</span>
              <span className="font-semibold text-slate-700 dark:text-slate-300">
                {formatDateEs(new Date(task.completedAt))}
              </span>
            </div>
          )}
        </div>
        
        {/* Gestión de días para tareas periódicas */}
        {task.periodicity !== Periodicity.NONE && onUpdatePeriodicTaskDayAssignment && onUpdatePeriodicTaskDayStatus && getPeriodicTaskDayInfo && (
          <PeriodicTaskDayManager
            task={task}
            users={users}
            onUpdateDayAssignment={(dayIndex, assignedTo) => {
              const specificDate = getPeriodicDayDate(dayIndex);
              return onUpdatePeriodicTaskDayAssignment(task.id, dayIndex, assignedTo, specificDate);
            }}
            onUpdateDayStatus={(dayIndex, status) => {
              const specificDate = getPeriodicDayDate(dayIndex);
              return onUpdatePeriodicTaskDayStatus(task.id, dayIndex, status, specificDate);
            }}
            getPeriodicTaskDayInfo={getPeriodicTaskDayInfo}
          />
        )}
        
        <div className="mt-6 flex justify-end">
          <button 
            onClick={onClose}
            className="bg-slate-200 hover:bg-slate-300 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-800 dark:text-slate-200 font-medium py-2 px-4 rounded-lg transition-colors"
          >
            {t('common.close')}
          </button>
        </div>
      </div>
    </Modal>
  );
};

export default TaskDetail;
