/**
 * Google Play Billing Service
 * Maneja las compras y suscripciones a través de Google Play para Android
 */

export interface GooglePlayProduct {
  productId: string;
  type: 'inapp' | 'subs';
  title: string;
  description: string;
  price: string;
  priceAmountMicros: number;
  priceCurrencyCode: string;
}

export interface GooglePlayPurchase {
  orderId: string;
  packageName: string;
  productId: string;
  purchaseTime: number;
  purchaseState: number;
  purchaseToken: string;
  acknowledged: boolean;
}

// IDs de productos definidos en Google Play Console
export const GOOGLE_PLAY_PRODUCTS = {
  premium_monthly_sub: 'housezen_premium_monthly_sub',
  premium_yearly_sub: 'housezen_premium_yearly_sub',
} as const;

/**
 * Interfaz del puente entre JavaScript y Android nativo
 * Estos métodos son proporcionados por el código Android WebView
 */
interface AndroidBillingBridge {
  // Inicializar el servicio de facturación
  initializeBilling: () => void;
  
  // Consultar productos disponibles
  queryProducts: (productIds: string) => void;
  
  // Iniciar flujo de compra
  launchPurchaseFlow: (productId: string, offerToken?: string) => void;
  
  // Consultar compras existentes
  queryPurchases: () => void;
  
  // Reconocer compra
  acknowledgePurchase: (purchaseToken: string) => void;
}

// Declarar el objeto global que Android inyectará
declare global {
  interface Window {
    AndroidBilling?: AndroidBillingBridge;
  }
}

class GooglePlayBillingService {
  private debugMode: boolean = true;
  private listeners: Map<string, ((data: any) => void)[]> = new Map();

  constructor() {
    // Registrar listeners para eventos desde Android
    if (typeof window !== 'undefined') {
      // @ts-ignore - Métodos llamados desde Android
      window.onBillingInitialized = this.handleBillingInitialized.bind(this);
      // @ts-ignore
      window.onProductsQueried = this.handleProductsQueried.bind(this);
      // @ts-ignore
      window.onPurchaseSuccess = this.handlePurchaseSuccess.bind(this);
      // @ts-ignore
      window.onPurchaseError = this.handlePurchaseError.bind(this);
      // @ts-ignore
      window.onPurchaseCancelled = this.handlePurchaseCancelled.bind(this);
    }
  }

  private log(message: string, data?: any) {
    if (this.debugMode) {
      console.log(`[GooglePlayBilling] ${message}`, data || '');
    }
  }

  /**
   * Verifica si estamos en un ambiente Android con soporte de facturación
   */
  isAvailable(): boolean {
    const available = typeof window !== 'undefined' && !!window.AndroidBilling;
    this.log('Checking availability', { available });
    return available;
  }

  /**
   * Inicializar el servicio de facturación
   */
  initialize(): Promise<void> {
    return new Promise((resolve, reject) => {
      if (!this.isAvailable()) {
        this.log('Billing not available');
        reject(new Error('Google Play Billing no está disponible'));
        return;
      }

      this.log('Initializing billing');
      
      // Registrar listener para inicialización
      this.once('initialized', () => {
        this.log('Billing initialized successfully');
        resolve();
      });

      this.once('error', (error) => {
        this.log('Billing initialization failed', error);
        reject(error);
      });

      // Llamar al método Android
      window.AndroidBilling!.initializeBilling();
    });
  }

  /**
   * Consultar productos disponibles
   */
  queryProducts(productIds: string[]): Promise<GooglePlayProduct[]> {
    return new Promise((resolve, reject) => {
      if (!this.isAvailable()) {
        reject(new Error('Google Play Billing no está disponible'));
        return;
      }

      this.log('Querying products', productIds);

      this.once('products', (products) => {
        this.log('Products queried', products);
        resolve(products);
      });

      this.once('error', (error) => {
        this.log('Error querying products', error);
        reject(error);
      });

      // Enviar IDs como string separado por comas
      window.AndroidBilling!.queryProducts(productIds.join(','));
    });
  }

  /**
   * Iniciar flujo de compra de suscripción
   */
  purchaseSubscription(productId: string, offerToken?: string): Promise<GooglePlayPurchase> {
    return new Promise((resolve, reject) => {
      if (!this.isAvailable()) {
        reject(new Error('Google Play Billing no está disponible'));
        return;
      }

      this.log('Launching purchase flow', { productId, offerToken });

      this.once('purchase_success', (purchase) => {
        this.log('Purchase successful', purchase);
        resolve(purchase);
      });

      this.once('purchase_error', (error) => {
        this.log('Purchase error', error);
        reject(error);
      });

      this.once('purchase_cancelled', () => {
        this.log('Purchase cancelled');
        reject(new Error('Compra cancelada por el usuario'));
      });

      window.AndroidBilling!.launchPurchaseFlow(productId, offerToken);
    });
  }

  /**
   * Consultar compras existentes
   */
  queryPurchases(): Promise<GooglePlayPurchase[]> {
    return new Promise((resolve, reject) => {
      if (!this.isAvailable()) {
        reject(new Error('Google Play Billing no está disponible'));
        return;
      }

      this.log('Querying purchases');

      this.once('purchases', (purchases) => {
        this.log('Purchases queried', purchases);
        resolve(purchases);
      });

      this.once('error', (error) => {
        this.log('Error querying purchases', error);
        reject(error);
      });

      window.AndroidBilling!.queryPurchases();
    });
  }

  /**
   * Reconocer una compra
   */
  acknowledgePurchase(purchaseToken: string): Promise<void> {
    return new Promise((resolve, reject) => {
      if (!this.isAvailable()) {
        reject(new Error('Google Play Billing no está disponible'));
        return;
      }

      this.log('Acknowledging purchase', purchaseToken);

      this.once('purchase_acknowledged', () => {
        this.log('Purchase acknowledged');
        resolve();
      });

      this.once('error', (error) => {
        this.log('Error acknowledging purchase', error);
        reject(error);
      });

      window.AndroidBilling!.acknowledgePurchase(purchaseToken);
    });
  }

  // Event handlers llamados desde Android
  private handleBillingInitialized() {
    this.log('Billing initialized callback');
    this.emit('initialized', null);
  }

  private handleProductsQueried(productsJson: string) {
    try {
      const products = JSON.parse(productsJson);
      this.emit('products', products);
    } catch (error) {
      this.log('Error parsing products', error);
      this.emit('error', error);
    }
  }

  private handlePurchaseSuccess(purchaseJson: string) {
    try {
      const purchase = JSON.parse(purchaseJson);
      this.emit('purchase_success', purchase);
    } catch (error) {
      this.log('Error parsing purchase', error);
      this.emit('error', error);
    }
  }

  private handlePurchaseError(errorMessage: string) {
    this.emit('purchase_error', new Error(errorMessage));
  }

  private handlePurchaseCancelled() {
    this.emit('purchase_cancelled', null);
  }

  // Sistema de eventos simple
  private on(event: string, callback: (data: any) => void) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event)!.push(callback);
  }

  private once(event: string, callback: (data: any) => void) {
    const wrappedCallback = (data: any) => {
      callback(data);
      this.off(event, wrappedCallback);
    };
    this.on(event, wrappedCallback);
  }

  private off(event: string, callback: (data: any) => void) {
    const callbacks = this.listeners.get(event);
    if (callbacks) {
      const index = callbacks.indexOf(callback);
      if (index > -1) {
        callbacks.splice(index, 1);
      }
    }
  }

  private emit(event: string, data: any) {
    const callbacks = this.listeners.get(event);
    if (callbacks) {
      callbacks.forEach(callback => callback(data));
    }
  }

  /**
   * Habilitar/deshabilitar modo debug
   */
  setDebugMode(enabled: boolean) {
    this.debugMode = enabled;
  }
}

// Exportar instancia singleton
export const googlePlayBillingService = new GooglePlayBillingService();
