    // --- STATS ---
    getStats(tasks: Task[], currentHomeId: string | null, userId: string, period: 'weekly' | 'monthly' | 'annually'): Stats {
        if (!currentHomeId) return { tasksCompleted: 0, pointsEarned: 0 };
        
        let tasksCompleted = 0;
        let pointsEarned = 0;

        tasks.forEach(task => {
            if (task.homeId !== currentHomeId) return;

            // Tareas no periódicas completadas por el usuario
            if (task.status === TaskStatus.COMPLETED && task.completedBy === userId && task.completedAt) {
                const completedDate = new Date(task.completedAt);
                let includeTask = false;
                if (period === 'weekly') includeTask = isThisWeek(completedDate);
                else if (period === 'monthly') includeTask = isThisMonth(completedDate);
                else includeTask = isThisYear(completedDate);

                if (includeTask) {
                    tasksCompleted += 1;
                    pointsEarned += task.points;
                }
            }

            // Tareas periódicas: contar días completados por el usuario
            if (task.registroDetallado) {
                Object.values(task.registroDetallado).forEach(dayRecord => {
                    if (dayRecord.completedBy === userId && dayRecord.status === TaskStatus.COMPLETED && dayRecord.completedAt) {
                        const completedDate = new Date(dayRecord.completedAt);
                        let includeDay = false;
                        if (period === 'weekly') includeDay = isThisWeek(completedDate);
                        else if (period === 'monthly') includeDay = isThisMonth(completedDate);
                        else includeDay = isThisYear(completedDate);

                        if (includeDay) {
                            tasksCompleted += 1;
                            pointsEarned += task.points;
                        }
                    }
                });
            }
            // Soporte para formato legacy (registro string)
            else if (task.registro && task.fechaInicio && task.completedBy === userId) {
                const startDate = new Date(task.fechaInicio);
                for (let i = 0; i < task.registro.length; i++) {
                    if (task.registro[i] === '2') { // '2' significa completada
                        const dayDate = new Date(startDate);
                        dayDate.setDate(startDate.getDate() + i);
                        
                        let includeDay = false;
                        if (period === 'weekly') includeDay = isThisWeek(dayDate);
                        else if (period === 'monthly') includeDay = isThisMonth(dayDate);
                        else includeDay = isThisYear(dayDate);

                        if (includeDay) {
                            tasksCompleted += 1;
                            pointsEarned += task.points;
                        }
                    }
                }
            }
        });

        return { tasksCompleted, pointsEarned };
    }

