    private findAvailableColorInHome(home: Home): string {
        const usedColors = new Set(
            home.memberIds
                .map(memberId => this.users.find(u => u.id === memberId)?.color)
                .filter((color): color is string => Boolean(color))
        );

        for (const color of USER_COLORS) {
            if (!usedColors.has(color)) return color;
        }
        return USER_COLORS[Math.floor(Math.random() * USER_COLORS.length)];
    }

    async createAnonymousMember(name: string, homeId: string): Promise<{ success: boolean; message: string; user?: User }> {
        if (!this.loggedInUser) {
            return { success: false, message: 'No hay usuario conectado.' };
        }

        const trimmedName = name.trim();
        if (!trimmedName) {
            return { success: false, message: 'Escribe un nombre para el miembro.' };
        }
        if (trimmedName.length > 16) {
            return { success: false, message: 'El nombre no puede superar 16 caracteres.' };
        }

        const homeIndex = this.homes.findIndex(h => h.id === homeId);
        if (homeIndex === -1) {
            return { success: false, message: 'La casa seleccionada no existe.' };
        }

        const home = this.homes[homeIndex];
        if (!home.memberIds.includes(this.loggedInUser.id)) {
            return { success: false, message: 'No tienes permisos para editar esta casa.' };
        }

        const duplicatedInHome = this.users.some(
            u => home.memberIds.includes(u.id) && u.name.trim().toLowerCase() === trimmedName.toLowerCase()
        );
        if (duplicatedInHome) {
            return { success: false, message: 'Ya existe un miembro con ese nombre en esta casa.' };
        }

        const newMember: User = {
            id: uuidv4(),
            name: trimmedName,
            email: undefined,
            avatar: '/user.svg',
            color: this.findAvailableColorInHome(home),
            plan: 'free',
            isAnonymous: true,
            createdAt: new Date().toISOString()
        };

        this.users.push(newMember);
        this.homes[homeIndex] = {
            ...home,
            memberIds: Array.from(new Set([...(home.memberIds || []), newMember.id]))
        };

        this.persist();
        return { success: true, message: `Miembro "${trimmedName}" creado.`, user: newMember };
    }
    
    async sendHomeInvitation(email: string, home: Home, inviter: User): Promise<{ success: boolean; message: string; }> {
        const userToInvite = this.users.find(u => u.email === email.toLowerCase());
        if (!userToInvite) return { success: false, message: "Usuario no encontrado. Asegúrate de que el correo esté registrado." };
        if (userToInvite.id === inviter.id) return { success: false, message: "No puedes invitarte a ti mismo." };
        if (home.memberIds.includes(userToInvite.id)) return { success: false, message: "Este usuario ya es miembro de la casa." };
        if (this.invitations.some(i => i.homeId === home.id && i.inviteeEmail === email.toLowerCase())) {
            return { success: false, message: "Ya se ha enviado una invitación a este usuario para esta casa." };
        }
        const newInvitation: HomeInvitation = {
            id: uuidv4(), homeId: home.id, homeName: home.name, invitedBy: inviter.id,
            inviteeEmail: email.toLowerCase(), status: 'pending'
        };
        this.invitations.push(newInvitation);
        this.persist();
        
        // Enviar notificación al usuario invitado
        try {
            await notificationService.sendHomeInvitationNotification(
                userToInvite.id,
                home,
                inviter.name,
                newInvitation.id
            );
        } catch (error) {
            console.error('Error al enviar notificación de invitación:', error);
        }
        
        return { success: true, message: `¡Invitación enviada a ${userToInvite.name}!` };
    }

    private findAvailableColor(userId: string): string {
        // Obtener todas las casas donde el usuario es miembro
        const userHomes = this.homes.filter(home => home.memberIds.includes(userId));
        
        // Obtener todos los usuarios únicos de todas las casas del usuario
        const allMemberIds = new Set<string>();
        userHomes.forEach(home => {
            home.memberIds.forEach(memberId => {
                if (memberId !== userId) { // Excluir al usuario actual
                    allMemberIds.add(memberId);
                }
            });
        });
        
        // Obtener los colores usados por estos usuarios
        const usedColors = new Set<string>();
        Array.from(allMemberIds).forEach(memberId => {
            const user = this.users.find(u => u.id === memberId);
            if (user && user.color) {
                usedColors.add(user.color);
            }
        });
        
        // Encontrar el primer color disponible
        for (const color of USER_COLORS) {
            if (!usedColors.has(color)) {
                return color;
            }
        }
        
        // Si todos los colores están ocupados, usar un color aleatorio
        return USER_COLORS[Math.floor(Math.random() * USER_COLORS.length)];
    }

    async respondToInvitation(invitationId: string, accept: boolean, currentUser: User): Promise<void> {
        const invIndex = this.invitations.findIndex(i => i.id === invitationId);
        if (invIndex === -1) return;
        const invitation = this.invitations[invIndex];

        if (accept) {
            // Agregar usuario a la casa
            this.homes = this.homes.map(h => {
                if (h.id === invitation.homeId) {
                    return { ...h, memberIds: [...new Set([...h.memberIds, currentUser.id])] };
                }
                return h;
            });
            
            // Asignar un color disponible al usuario
            const availableColor = this.findAvailableColor(currentUser.id);
            const userIndex = this.users.findIndex(u => u.id === currentUser.id);
            if (userIndex !== -1) {
                this.users[userIndex] = { ...this.users[userIndex], color: availableColor };
                // Actualizar el usuario logueado si es el mismo
                if (this.loggedInUser && this.loggedInUser.id === currentUser.id) {
                    this.loggedInUser = { ...this.loggedInUser, color: availableColor };
                }
            }
        }
        this.invitations.splice(invIndex, 1);
        this.persist();
    }
    
