import { User, Home, LimitType, Periodicity, Task, NewTaskPayload } from '../types';
import { useAppConfig } from './useAppConfig';
import { useI18n } from '../i18n/I18nProvider';

interface LimitCheckResult {
  isLimited: boolean;
  message?: string;
}

export const useSubscription = (currentUser: User | null, userHomes: Home[], currentHome: Home | undefined, tasks: Task[] = []) => {
  const { appConfig } = useAppConfig();
  const { t } = useI18n();
  const plan = currentUser?.plan || 'free';
  const normalizedEmail = String(currentUser?.email || '').trim().toLowerCase();
  const hasPremiumBypass = !!normalizedEmail && (appConfig.premium.premiumBypassEmails || []).includes(normalizedEmail);
  const subscriptionStatus = currentUser?.subscriptionStatus;
  const expiryTime = currentUser?.subscriptionExpiryTime;
  const hasExpired = typeof expiryTime === 'number' && expiryTime > 0 && expiryTime < Date.now();
  
  // Un usuario es premium si tiene plan premium Y su suscripción está activa o cancelada al final del período
  const isPremium = hasPremiumBypass || (
    plan === 'premium' &&
    (subscriptionStatus === 'active' || subscriptionStatus === 'cancel_at_period_end') &&
    !hasExpired
  );
  
  // Información adicional sobre el estado de la suscripción
  const isSubscriptionCanceled = subscriptionStatus === 'cancel_at_period_end';
  const isSubscriptionActive = subscriptionStatus === 'active';

  const checkLimit = (limitType: LimitType, taskData?: NewTaskPayload): LimitCheckResult => {
    switch (limitType) {
      case LimitType.HOMES:
        const maxHomes = isPremium ? appConfig.limits.premiumMaxHomes : appConfig.limits.freeMaxHomes;
        if (userHomes.length >= maxHomes) {
          return {
            isLimited: true,
            message: isPremium
              ? t('limits.homes.premium', { max: appConfig.limits.premiumMaxHomes })
              : t('limits.homes.free', {
                  max: appConfig.limits.freeMaxHomes,
                  plural: appConfig.limits.freeMaxHomes === 1 ? '' : 's',
                  premiumMax: appConfig.limits.premiumMaxHomes,
                }),
          };
        }
        break;
      
      case LimitType.MEMBERS:
        if (isPremium) return { isLimited: false };
        if (currentHome && currentHome.memberIds.length >= appConfig.limits.freeMaxMembersPerHome) {
            return {
                isLimited: true,
                message: t('limits.members.free', { max: appConfig.limits.freeMaxMembersPerHome }),
            }
        }
        break;

      case LimitType.TASKS:
        if (isPremium) return { isLimited: false };
        if (currentHome && (currentHome.activeTaskCount || 0) >= appConfig.limits.freeMaxActiveTasks) {
            return {
                isLimited: true,
                message: t('limits.tasks.free', { max: appConfig.limits.freeMaxActiveTasks }),
            }
        }
        break;
        
      case LimitType.PERIODIC_TASKS:
        if (isPremium) return { isLimited: false };
        // Solo verificar si estamos intentando crear una tarea periódica
        if (taskData && taskData.periodicity !== Periodicity.NONE && currentHome) {
          // Contar cuántas tareas periódicas diferentes tiene el usuario
          const periodicTaskTitles = new Set();
          
          tasks
            .filter(t => 
              t.homeId === currentHome.id && 
              t.periodicity !== Periodicity.NONE
            )
            .forEach(task => {
              periodicTaskTitles.add(task.title);
            });
          
          if (periodicTaskTitles.size >= appConfig.limits.freeMaxPeriodicTaskTemplates && !periodicTaskTitles.has(taskData.title)) {
            return {
              isLimited: true,
              message: t('limits.periodic.free', { max: appConfig.limits.freeMaxPeriodicTaskTemplates }),
            };
          }
        }
        break;
      
      case LimitType.REWARDS:
        if (isPremium) return { isLimited: false };
        if (currentHome) {
          // Contar premios activos en el hogar actual
          const activeRewards = tasks.filter(r => 
            r.homeId === currentHome.id && 
            r.isActive
          ).length;
          
          if (activeRewards >= appConfig.limits.freeMaxActiveRewards) {
            return {
              isLimited: true,
              message: t('limits.rewards.free', {
                max: appConfig.limits.freeMaxActiveRewards,
                plural: appConfig.limits.freeMaxActiveRewards === 1 ? '' : 's',
                premiumMax: appConfig.limits.premiumMaxActiveRewards,
              }),
            };
          }
        }
        break;
    }

    return { isLimited: false };
  };

  return {
    plan,
    isPremium,
    hasPremiumBypass,
    subscriptionStatus,
    isSubscriptionCanceled,
    isSubscriptionActive,
    checkLimit,
  };
};
