// import { FieldValue } from "firebase/firestore";

export type UserPlan = 'free' | 'premium';

export type HomeMode = 'LOCAL' | 'PREMIUM';

export type SubscriptionStatus = 'active' | 'cancelled' | 'expired' | 'pending' | 'cancel_at_period_end' | 'grace_period' | 'on_hold';

export interface Home {
  id: string;
  name: string;
  adminIds: string[];
  memberIds: string[];
  mode: HomeMode; // 'LOCAL' o 'PREMIUM'
  createdBy: string;
  createdAt: string; // ISO string
  activeTaskCount?: number; // Calculated field for freemium limits
}

export interface User {
  id: string;
  name: string;
  email?: string ; // Opcional si es usuario local anónimo
  avatar: string;
  color: string;
  plan: UserPlan;
  isAnonymous?: boolean; // Usuario local sin cuenta
  allowCloudAccess?: boolean; // Permite usar Firebase aunque sea anónimo/sin email (invitaciones por URL)
  subscriptionId?: string;
  subscriptionStatus?: SubscriptionStatus;
  subscriptionEndsAt?: string; // ISO string
  subscriptionExpiryTime?: number; // Epoch ms (Stripe/Apple/Google/trial)
  subscriptionSource?: string;
  canceledAt?: string;
  createdAt?: string; // ISO string
}

export enum TaskStatus {
  PENDING = 'Pendiente',
  IN_PROGRESS = 'En proceso',
  COMPLETED = 'Completada',
  NOT_DONE = 'No realizada',
  DELETED = 'Eliminada',
}

export enum Periodicity {
  NONE = 'Nunca',
  DAILY = 'Diaria',
  WEEKLY = 'Semanal',
  MONTHLY = 'Mensual',
  CUSTOM_DAYS = 'Personalizada',
}

export type ReminderUnit = 'minutes' | 'hours' | 'days';

export interface TaskReminder {
  enabled: boolean;
  amount: number;
  unit: ReminderUnit;
}

// Daily task record for periodic tasks
export interface DailyTaskRecord {
  status: TaskStatus; // Estado del día específico
  date: string; // Fecha específica del día (ISO string)
  day: number; // Número del día (0, 1, 2, etc.) dentro de la tarea periódica
  assignedTo?: string | null; // Usuario asignado para este día específico
  completedBy?: string; // Usuario que completó la tarea este día
  completedAt?: string; // Timestamp de cuando se completó este día
}

// Registry for periodic tasks - maps day number to task record
export type PeriodicTaskRegistry = Record<string, DailyTaskRecord>;

export interface Task {
  id: string;
  title: string;
  description: string;
  emoji: string;
  points: number;
  dueDate: string; // ISO string - Para tareas no periódicas o primera instancia de periódicas
  fechaInicio?: string; // ISO string - Fecha de inicio para tareas periódicas
  fechaFin?: string; // ISO string - Fecha de fin para tareas periódicas
  registro?: string; // String de caracteres para seguimiento diario (LEGACY): "0"=pendiente, "1"=completada, "2"=realizada, "3"=no realizada
  registroDetallado?: PeriodicTaskRegistry; // Nuevo sistema detallado para asignaciones y estados por día
  endDate?: string | null; // ISO string para fecha límite de tareas periódicas (campo legacy)
  periodicity: Periodicity;
  customDays?: number | null; // Número de días para periodicidad personalizada
  reminder?: TaskReminder | null; // Recordatorio local antes del vencimiento
  status: TaskStatus;
  createdBy: string;
  assignedTo?: string | null; // User ID o null (para tareas no periódicas o asignación por defecto)
  completedBy?: string;
  completedAt?: string; // ISO string
  homeId: string;
  createdAt: string; // Firestore server timestamp o ISO string para local
}

export type NewTaskPayload = Omit<Task, 'id' | 'status' | 'createdBy' | 'completedBy' | 'completedAt' | 'createdAt'>;

// Rewards System Types
export enum RewardStatus {
  PENDING = 'Pendiente',
  GRANTED = 'Concedido',
  REJECTED = 'Rechazado'
}

export interface Reward {
  id: string;
  title: string;
  description: string;
  emoji: string;
  pointsCost: number;
  homeId: string;
  createdBy: string; // Admin que creó el premio
  createdAt: string;
  isActive: boolean; // Para poder desactivar premios sin eliminarlos
}

export interface RewardClaim {
  id: string;
  rewardId: string;
  userId: string;
  homeId: string;
  pointsSpent: number;
  status: RewardStatus;
  claimedAt: string;
  processedAt?: string; // Cuando el admin procesó la solicitud
  processedBy?: string; // Admin que procesó la solicitud
  notes?: string; // Notas del administrador
}

export type NewRewardPayload = Omit<Reward, 'id' | 'createdBy' | 'createdAt'>;

