import React, { useState, useEffect } from 'react';
import { useData } from '../hooks/useData';
import { useSubscription } from '../hooks/useSubscription';
import { usePlatform } from '../hooks/usePlatform';
import { Home, User, View, LimitType } from '../types';
import { CheckIcon, XMarkIcon, PencilIcon } from './Icons';
import { USE_FIREBASE } from '../config';
import { USER_COLORS } from '../constants';
import DeleteAccountModal from './DeleteAccountModal';
import BugReportModal from './BugReportModal';
import CancelSubscriptionModal from './CancelSubscriptionModal';
import { firebaseDataService } from '../services/firebaseDataService';
import { notificationService } from '../services/notificationService';
import { auth } from '../services/firebase';
import { useAppConfig } from '../hooks/useAppConfig';
import { useI18n } from '../i18n/I18nProvider';
import { SupportedLanguage } from '../i18n/translations';
import { isPremiumPurchaseEnabledForPlatform } from '../services/appConfigService';

type SettingsProps = ReturnType<typeof useData> & {
    onViewChange: (view: View) => void;
    onLimitReached: (reason: string) => void;
    leaveHome: (homeId: string, userId: string) => Promise<{ success: boolean; message: string }>;
    setCurrentHomeId: (homeId: string) => void;
    removeUserFromHome: (homeId: string, userId: string) => Promise<void>;
    deleteAccount: (password?: string) => Promise<{ success: boolean; message: string }>;
};

const SettingsPage: React.FC<SettingsProps> = ({
    currentUser, userHomes, users, createHome, updateHome, updateCurrentUser,
    uploadAvatar, createHomeInviteLink, createAnonymousMember,
    onViewChange, onLimitReached, togglePremium, leaveHome, removeUserFromHome, logout,
    deleteAccount
}) => {
    const { checkLimit, isPremium, isSubscriptionCanceled } = useSubscription(currentUser, userHomes, userHomes[0]);
    const { isNative, platform } = usePlatform();
    const { appConfig } = useAppConfig();
    const { t, language, setLanguage, supportedLanguages, languageLabels } = useI18n();

    const [message, setMessage] = useState<{type: 'success' | 'error', text: string} | null>(null);
    const [loading, setLoading] = useState<Record<string, boolean>>({});
    const [userName, setUserName] = useState(currentUser?.name || '');
    const [userAvatar, setUserAvatar] = useState(currentUser?.avatar || '/user.svg');
    const [userColor, setUserColor] = useState(currentUser?.color || USER_COLORS[0]);
    const [userPassword, setUserPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [avatarFile, setAvatarFile] = useState<File | null>(null);
    const [newHomeName, setNewHomeName] = useState('');
    const [editingHomeId, setEditingHomeId] = useState<string | null>(null);
    const [editingHomeName, setEditingHomeName] = useState('');
    const [selectedHomeIdForInvite, setSelectedHomeIdForInvite] = useState<string | null>(null);
    const [selectedHomeIdForAnonymous, setSelectedHomeIdForAnonymous] = useState<string | null>(null);
    const [anonymousMemberName, setAnonymousMemberName] = useState('');
    const [generatedInviteUrl, setGeneratedInviteUrl] = useState('');
    const [leavingHomeId, setLeavingHomeId] = useState<string | null>(null);
    const [confirmLeaveHomeId, setConfirmLeaveHomeId] = useState<string | null>(null);
    const [confirmRemove, setConfirmRemove] = useState<{homeId: string, user: User} | null>(null);
    const [inviteFeedback, setInviteFeedback] = useState<{type: 'success' | 'error', text: string} | null>(null);
    const [removedUserNotification, setRemovedUserNotification] = useState<{userName: string, homeName: string} | null>(null);
    const [showDeleteAccountModal, setShowDeleteAccountModal] = useState(false);
    const [showBugReportModal, setShowBugReportModal] = useState(false);
    const [showCancelSubscriptionModal, setShowCancelSubscriptionModal] = useState(false);
    const [isGoogleUser, setIsGoogleUser] = useState(false);
    const purchaseEnabledOnPlatform = isPremiumPurchaseEnabledForPlatform(
        appConfig,
        isNative ? (platform as 'ios' | 'android') : 'web'
    );

    // Verificar si el usuario fue creado con Google
    useEffect(() => {
        if (USE_FIREBASE && auth.currentUser) {
            const hasGoogleProvider = auth.currentUser.providerData.some(provider => provider.providerId === 'google.com');
            const hasPasswordProvider = auth.currentUser.providerData.some(provider => provider.providerId === 'password');
            setIsGoogleUser(hasGoogleProvider && !hasPasswordProvider);
        }
    }, [currentUser]);

    useEffect(() => {
        // Solo actualizar si los valores han cambiado realmente y el usuario no está editando
        if (currentUser && currentUser.name !== userName && document.activeElement?.id !== 'userName') {
            setUserName(currentUser.name);
            }
        if(currentUser && currentUser.avatar !== userAvatar && userAvatar !== '/user.svg') {
            setUserAvatar(currentUser.avatar || '/user.svg');
        }
        // Inicializar el color solo cuando se carga el componente por primera vez
        if(currentUser && userColor === USER_COLORS[0] && currentUser.color) {
            setUserColor(currentUser.color);
        }
        // Solo actualizar si no hay un valor seleccionado y hay casas disponibles
        if (userHomes.length > 0 && !selectedHomeIdForInvite) {
            setSelectedHomeIdForInvite(userHomes[0].id);
        }
        if (userHomes.length > 0 && !selectedHomeIdForAnonymous) {
            setSelectedHomeIdForAnonymous(userHomes[0].id);
        }
    }, [currentUser, userHomes, selectedHomeIdForInvite, selectedHomeIdForAnonymous, userName, userAvatar]);

    const showMessage = (type: 'success' | 'error', text: string) => {
        setMessage({ type, text });
        setTimeout(() => setMessage(null), 4000);
    };

    const handleReviewClick = () => {
        const platform = (window as any)?.Capacitor?.getPlatform?.();
        const reviewUrl = platform === 'ios'
            ? appConfig.review.iosUrl
            : platform === 'android'
                ? appConfig.review.androidUrl
                : '';

        if (!reviewUrl) {
            showMessage('error', t('settings.review.urlMissing'));
            return;
        }

        window.open(reviewUrl, '_blank', 'noopener,noreferrer');
    };

    const handleAvatarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setAvatarFile(file);
            const reader = new FileReader();
            reader.onloadend = () => setUserAvatar(reader.result as string);
            reader.readAsDataURL(file);
        }
    };

    const handleUpdateProfile = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading({ ...loading, profile: true });
        try {
            if (userPassword && userPassword !== confirmPassword) {
                showMessage('error', t('settings.passwords.notMatch'));
                setLoading({ ...loading, profile: false });
                return;
            }

            // Validar contraseña para usuarios de Google
            if (isGoogleUser && userPassword) {
                if (userPassword.length < 8) {
                    showMessage('error', t('settings.passwords.minLength'));
                    setLoading({ ...loading, profile: false });
                    return;
                }
                if (!/[A-Z]/.test(userPassword)) {
                    showMessage('error', t('settings.passwords.uppercase'));
                    setLoading({ ...loading, profile: false });
                    return;
                }
                if (!/[0-9]/.test(userPassword)) {
                    showMessage('error', t('settings.passwords.number'));
                    setLoading({ ...loading, profile: false });
                    return;
                }
                if (!/[!@#$%^&*(),.?":{}|<>]/.test(userPassword)) {
                    showMessage('error', t('settings.passwords.special'));
                    setLoading({ ...loading, profile: false });
                    return;
                }
            }
            
            let avatarUrl = userAvatar;
            if (avatarFile) {
                try {
                    avatarUrl = await uploadAvatar(avatarFile);
                } catch (error) {
                    console.error('Error al subir avatar:', error);
                    showMessage('error', t('settings.profile.avatarUploadError'));
                    setLoading({ ...loading, profile: false });
                    return;
                }
            }
            
            const updates: Partial<User> & {password?: string} = { 
                name: userName, 
                avatar: avatarUrl,
                color: userColor
            };
            if (userPassword) updates.password = userPassword;
            
            const result = await updateCurrentUser(updates);
            
            if (result.success && isGoogleUser && userPassword) {
                    showMessage('success', t('settings.passwords.setSuccess'));
                // Actualizar el estado para reflejar que ya no es solo usuario de Google
                setIsGoogleUser(false);
            } else {
                showMessage(result.success ? 'success' : 'error', result.message);
            }
            
            if (result.success) {
                setUserPassword('');
                setConfirmPassword('');
                setAvatarFile(null);
            }
        } catch (error) {
            console.error('Error al actualizar perfil:', error);
            showMessage('error', t('settings.profile.updateError'));
        } finally {
            setLoading({ ...loading, profile: false });
        }
    };

    const handleCancelSubscription = async () => {
        setShowCancelSubscriptionModal(false);
        setLoading({ ...loading, subscription: true });
        try {
            const result = await firebaseDataService.cancelSubscription();
            showMessage(result.success ? 'success' : 'error', result.message);
        } catch (error) {
            console.error('Error al cancelar suscripción:', error);
            showMessage('error', t('settings.subscription.cancelError'));
        } finally {
            setLoading({ ...loading, subscription: false });
        }
    };
    
    const handleCreateHome = async (e: React.FormEvent) => {
        e.preventDefault();
        const limit = checkLimit(LimitType.HOMES);
        if(limit.isLimited) {
            onLimitReached(limit.message!);
            return;
        }
        if (newHomeName.trim()) {
            setLoading({ ...loading, createHome: true });
            
            // Track analytics for home creation attempt
            if (currentUser) {
                await notificationService.recordPremiumFeatureAttempt(
                    currentUser.uid,
                    'home_creation',
                    {
                        homeName: newHomeName.trim(),
                        currentHomesCount: userHomes.length
                    }
                );
            }
            
            await createHome(newHomeName.trim());
            showMessage('success', t('settings.homes.created', { name: newHomeName.trim() }));
            setNewHomeName('');
            setLoading({ ...loading, createHome: false });
        }
    };

    const handleUpdateHome = async (homeId: string) => {
        if (editingHomeName.trim()) {
            setLoading({ ...loading, [`home_${homeId}`]: true });
            await updateHome(homeId, { name: editingHomeName.trim() });
            showMessage('success', t('settings.homes.updated'));
            setEditingHomeId(null); setEditingHomeName('');
            setLoading({ ...loading, [`home_${homeId}`]: false });
        }
    };

    const handleCreateInviteLink = async (e: React.FormEvent) => {
        e.preventDefault();
        const limit = checkLimit(LimitType.MEMBERS);
        if (limit.isLimited) {
            onLimitReached(limit.message!);
            return;
        }
        if (!isPremium) {
            setInviteFeedback({ type: 'error', text: t('settings.invite.premiumRequired') });
            return;
        }
        if (!selectedHomeIdForInvite) {
            setInviteFeedback({ type: 'error', text: t('settings.homes.selectHome') });
            return;
        }

        setLoading({ ...loading, invite: true });
        const result = await createHomeInviteLink(selectedHomeIdForInvite);
        if (result.success && result.inviteUrl) {
            setGeneratedInviteUrl(result.inviteUrl);
            setInviteFeedback({ type: 'success', text: t('settings.invite.generatedSuccess') });
            try {
                await navigator.clipboard.writeText(result.inviteUrl);
            } catch {
                // Si falla el portapapeles, el usuario aún puede copiar manualmente.
            }
        } else {
            setInviteFeedback({ type: 'error', text: result.message });
        }
        setLoading({ ...loading, invite: false });
    };

    const handleCreateAnonymousMember = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!createAnonymousMember) {
            showMessage('error', t('settings.anonymous.notAvailable'));
            return;
        }
        if (!selectedHomeIdForAnonymous) {
            showMessage('error', t('settings.homes.selectHome'));
            return;
        }
        if (!anonymousMemberName.trim()) {
            showMessage('error', t('settings.anonymous.nameRequired'));
            return;
        }

        setLoading({ ...loading, anonymousMember: true });
        try {
            const result = await createAnonymousMember(anonymousMemberName.trim(), selectedHomeIdForAnonymous);
            showMessage(result.success ? 'success' : 'error', result.message);
            if (result.success) {
                setAnonymousMemberName('');
            }
        } catch (error: any) {
            showMessage('error', error?.message || t('settings.anonymous.createError'));
        } finally {
            setLoading({ ...loading, anonymousMember: false });
        }
    };

    if (!currentUser) return null;

    // Añadir función para eliminar usuario de una casa
    const handleRemoveUser = async (homeId: string, userId: string) => {
        const user = users.find(u => u.id === userId);
        if (!user) return;
        setConfirmRemove({ homeId, user });
    };

    const confirmRemoveUser = async () => {
        if (!confirmRemove) return;
        setLoading({ ...loading, [`remove_${confirmRemove.user.id}`]: true });
        try {
            // Buscar el nombre de la casa para la notificación antes de eliminar al usuario
            const homeName = userHomes.find(h => h.id === confirmRemove.homeId)?.name || 'la casa';
            
            await removeUserFromHome(confirmRemove.homeId, confirmRemove.user.id);
            
            // Mostrar mensaje de éxito al administrador que elimina al usuario
            showMessage('success', t('settings.homes.userRemoved', { user: confirmRemove.user.name, home: homeName }));
            
            // Mostrar notificación simulando que el usuario eliminado la recibe
            // En una implementación real, esto enviaría una notificación push o email al usuario
            setRemovedUserNotification({
                userName: confirmRemove.user.name,
                homeName: homeName
            });
            
            console.log(`Se ha notificado a ${confirmRemove.user.name} que ha sido eliminado de ${homeName}`);
            
            // Nota: En una implementación real, la notificación al usuario eliminado
            // se manejaría en el backend (firebaseDataService.ts) y se enviaría
            // directamente al dispositivo del usuario mediante Firebase Cloud Messaging
            // o por correo electrónico.
        } catch (e: any) {
            showMessage('error', e.message || t('settings.homes.removeError'));
        } finally {
            setLoading({ ...loading, [`remove_${confirmRemove.user.id}`]: false });
            setConfirmRemove(null);
        }
    };
    const cancelRemoveUser = () => setConfirmRemove(null);
    const closeRemovedUserNotification = () => setRemovedUserNotification(null);

    const handleLeaveHome = async (homeId: string) => {
        if (!currentUser) return;
        setConfirmLeaveHomeId(homeId);
    };

    const confirmLeave = async () => {
        if (!currentUser || !confirmLeaveHomeId) return;
        setLoading({ ...loading, [`leave_${confirmLeaveHomeId}`]: true });
        try {
            const result = await leaveHome(confirmLeaveHomeId, currentUser.id);
            showMessage(result.success ? 'success' : 'error', result.message);
        } catch (error) {
            showMessage('error', t('settings.homes.leaveError'));
        } finally {
            setLoading({ ...loading, [`leave_${confirmLeaveHomeId}`]: false });
            setLeavingHomeId(null);
            setConfirmLeaveHomeId(null);
        }
    };
    const cancelLeave = () => setConfirmLeaveHomeId(null);
    const homesLimit = checkLimit(LimitType.HOMES);

    return (
        <div className="space-y-10 pb-8 sm:pb-12">
            <div className="flex justify-between items-center">
                <h2 className="text-3xl font-bold text-slate-900 dark:text-white">{t('settings.title')}</h2>
                {isPremium && (
                    <button 
                        onClick={() => setShowCancelSubscriptionModal(true)}
                        className="font-semibold text-white bg-red-500 hover:bg-red-600 px-4 py-2 rounded-lg shadow-lg transition-transform hover:scale-105"
                    >
                        {t('settings.cancelMembership')}
                    </button>
                )}
            </div>
            
            {/* Mensaje de estado de suscripción */}
            {isSubscriptionCanceled && (
                <div className="p-4 rounded-md text-sm mb-6 bg-yellow-100 dark:bg-yellow-900/50 text-yellow-700 dark:text-yellow-200 border border-yellow-300 dark:border-yellow-600">
                    {t('settings.subscriptionCanceled')}
                </div>
            )}
            
            {message && <div className={`p-4 rounded-md text-sm mb-6 ${message.type === 'success' ? 'bg-green-100 dark:bg-green-900/50 text-green-700 dark:text-green-200' : 'bg-red-100 dark:bg-red-900/50 text-red-700 dark:text-red-200'}`}>{message.text}</div>}

            <div className="p-6 bg-white dark:bg-slate-800/50 rounded-xl shadow-md">
                <h3 className="text-xl font-bold mb-4">{t('settings.language.title')}</h3>
                <div className="max-w-xs">
                    <label className="text-sm font-medium text-gray-600 dark:text-gray-300 block mb-1">
                        {t('settings.language.label')}
                    </label>
                    <select
                        value={language}
                        onChange={(e) => setLanguage(e.target.value as SupportedLanguage)}
                        className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded"
                    >
                        {supportedLanguages.map((lang) => (
                            <option key={lang} value={lang}>
                                {languageLabels[lang]}
                            </option>
                        ))}
                    </select>
                </div>
            </div>

            {/* My Profile */}
            <div className="p-6 bg-white dark:bg-slate-800/50 rounded-xl shadow-md">
                <h3 className="text-xl font-bold mb-4">{t('settings.profile.title')}</h3>
                <form onSubmit={handleUpdateProfile} className="space-y-4">
                    {/* ... form content ... */}
                     <div className="flex items-center gap-4">
                        {/* Avatar oculto pero mantenido en el DOM */}
                        <img 
                            src={userAvatar} 
                            alt="Avatar" 
                            className="hidden" 
                        />
                        <div className="flex-grow space-y-2">
                             <div>
                                <label className="text-sm font-medium text-gray-600 dark:text-gray-300 block">{t('settings.profile.name')}</label>
                                <input 
                                    type="text" 
                                    id="userName"
                                    value={userName} 
                                    onChange={e => setUserName(e.target.value)} 
                                    maxLength={16}
                                    required 
                                    className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded mt-1" 
                                />
                                <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">{t('settings.profile.chars', { current: userName.length, max: 16 })}</p>
                            </div>
                             <div className="hidden">
                                <label className="text-sm font-medium text-gray-600 dark:text-gray-300 block">{t('settings.profile.avatar')}</label>
                                <div className="flex items-center gap-3 mt-1">
                                    {/* Avatar oculto pero mantenido en el DOM */}
                                    <img 
                                        src={userAvatar} 
                                        alt="Avatar" 
                                        className="hidden" 
                                    />
                                    {isPremium ? (
                                        <input 
                                            type="file" 
                                            accept="image/*" 
                                            onChange={handleAvatarChange} 
                                            className="text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-50 file:text-primary-700 hover:file:bg-primary-100 dark:file:bg-slate-700 dark:file:text-slate-200" 
                                        />
                                    ) : (
                                        <div className="flex items-center gap-1 text-sm text-amber-600 dark:text-amber-400">
                                            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4">
                                                <path fillRule="evenodd" d="M10 1a4.5 4.5 0 00-4.5 4.5V9H5a2 2 0 00-2 2v6a2 2 0 002 2h10a2 2 0 002-2v-6a2 2 0 00-2-2h-.5V5.5A4.5 4.5 0 0010 1zm3 8V5.5a3 3 0 10-6 0V9h6z" clipRule="evenodd" />
                                            </svg>
                                            <span>{t('settings.premiumFeature')}</span>
                                        </div>
                                    )}
                                </div>
                                <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                                    {isPremium ? t('settings.profile.avatarHintPremium') : t('settings.profile.avatarHintFree')}
                                </p>
                            </div>
                            <div>
                                <label className="text-sm font-medium text-gray-600 dark:text-gray-300 block">{t('settings.profile.homeColor')}</label>
                                {isPremium ? (
                                    <>
                                        <div className="flex flex-wrap gap-2 mt-1">
                                            {USER_COLORS.map((color, index) => {
                                                // Verificar si el color ya está siendo usado por otro miembro en alguna de las casas del usuario
                                                const isColorUsedByOthers = userHomes.some(home => {
                                                    // Obtener todos los usuarios de esta casa excepto el usuario actual
                                                    const otherUsers = users.filter(u => 
                                                        home.memberIds.includes(u.id) && u.id !== currentUser.id
                                                    );
                                                    // Verificar si alguno de esos usuarios ya tiene este color
                                                    return otherUsers.some(u => u.color === color);
                                                });
                                                
                                                return (
                                                    <button
                                                        key={index}
                                                        type="button"
                                                        onClick={() => !isColorUsedByOthers && setUserColor(color)}
                                                        disabled={isColorUsedByOthers}
                                                        className={`w-8 h-8 rounded-full transition-transform 
                                                            ${userColor === color ? 'ring-2 ring-offset-2 ring-primary-500 scale-110' : !isColorUsedByOthers ? 'hover:scale-110' : ''}
                                                            ${isColorUsedByOthers ? 'opacity-30 cursor-not-allowed' : 'cursor-pointer'}`}
                                                        style={{ backgroundColor: color }}
                                                        aria-label={`Color ${index + 1}`}
                                                        title={isColorUsedByOthers ? t('settings.profile.colorUsed') : t('settings.profile.colorOption', { index: index + 1 })}
                                                    />
                                                );
                                            })}
                                        </div>
                                        <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                                            {t('settings.profile.colorHintUsed')}
                                        </p>
                                    </>
                                ) : (
                                    <div className="mt-1">
                                        <div className="flex items-center gap-2">
                                            <div className="w-8 h-8 rounded-full" style={{ backgroundColor: userColor }}></div>
                                            <div className="flex items-center gap-1 text-sm text-amber-600 dark:text-amber-400">
                                                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4">
                                                    <path fillRule="evenodd" d="M10 1a4.5 4.5 0 00-4.5 4.5V9H5a2 2 0 00-2 2v6a2 2 0 002 2h10a2 2 0 002-2v-6a2 2 0 00-2-2h-.5V5.5A4.5 4.5 0 0010 1zm3 8V5.5a3 3 0 10-6 0V9h6z" clipRule="evenodd" />
                                                </svg>
                                                <span>{t('settings.premiumFeature')}</span>
                                            </div>
                                        </div>
                                        <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                                            {t('settings.profile.colorHintFree')}
                                        </p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                    {isGoogleUser && (
                        <div className="mb-4 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
                            <div className="flex items-start gap-3">
                                <div className="flex-shrink-0">
                                    <svg className="w-5 h-5 text-blue-500 mt-0.5" fill="currentColor" viewBox="0 0 20 20">
                                        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                                    </svg>
                                </div>
                                <div>
                                    <h4 className="text-sm font-medium text-blue-800 dark:text-blue-200">{t('settings.profile.googleAccountTitle')}</h4>
                                    <p className="text-sm text-blue-700 dark:text-blue-300 mt-1">
                                        {t('settings.profile.googleAccountDescription')}
                                    </p>
                                    <button
                                        type="button"
                                        onClick={() => logout()}
                                        className="mt-3 inline-flex items-center justify-center rounded-md bg-slate-800 hover:bg-slate-900 dark:bg-slate-700 dark:hover:bg-slate-600 text-white text-sm font-semibold px-3 py-1.5"
                                    >
                                        {t('header.logout')}
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}
                    <div className="grid md:grid-cols-2 gap-4">
                        <div>
                            <label className="text-sm font-medium text-gray-600 dark:text-gray-300 block">
                                {isGoogleUser ? t('settings.passwords.set') : t('settings.passwords.new')}
                            </label>
                            <input 
                                type="password" 
                                value={userPassword} 
                                onChange={e => setUserPassword(e.target.value)} 
                                placeholder={isGoogleUser ? t('settings.passwords.setPlaceholder') : t('settings.passwords.optionalPlaceholder')} 
                                className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded mt-1" 
                            />
                        </div>
                         <div>
                            <label className="text-sm font-medium text-gray-600 dark:text-gray-300 block">{t('settings.passwords.confirm')}</label>
                            <input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded mt-1" />
                        </div>
                    </div>
                    <div className="flex justify-end"><button type="submit" disabled={loading['profile']} className="py-2 px-4 bg-primary-600 hover:bg-primary-700 text-white rounded-md font-bold disabled:bg-primary-300">{loading['profile'] ? t('settings.saving') : t('settings.saveChanges')}</button></div>
                </form>
            </div>
            
            <div className="p-6 bg-white dark:bg-slate-800/50 rounded-xl shadow-md">
                 <h3 className="text-xl font-bold mb-4">{t('settings.homes.title')}</h3>
                 {/* Home management logic from original file */}
                  <div className="space-y-4 mb-6">
    {userHomes.map(home => (
        <div key={home.id} className="p-4 border border-slate-200 dark:border-slate-700 rounded-lg">
            <div className="flex justify-between items-start">
                {editingHomeId === home.id ? (
                    <div className="flex-grow flex gap-2 items-center">
                        <input 
                          type="text" 
                          value={editingHomeName} 
                          onChange={e => setEditingHomeName(e.target.value)} 
                          maxLength={30}
                          className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded" 
                        />
                        <button onClick={() => handleUpdateHome(home.id)} disabled={loading[`home_${home.id}`]} className="p-2 bg-green-500 text-white rounded-md disabled:bg-green-300"><CheckIcon className="w-5 h-5" /></button>
                        <button onClick={() => setEditingHomeId(null)} className="p-2 bg-red-500 text-white rounded-md"><XMarkIcon className="w-5 h-5" /></button>
                    </div>
                ) : (
                    <>
                        <h4 className="font-bold text-lg text-primary-600 dark:text-primary-400">{home.name}</h4>
                        <button onClick={() => { setEditingHomeId(home.id); setEditingHomeName(home.name); }} className="text-slate-500 hover:text-primary-600 dark:text-slate-400 dark:hover:text-primary-400"><PencilIcon className="w-5 h-5" /></button>
                    </>
                )}
            </div>
            <p className="text-sm font-semibold mt-2 mb-1">{t('settings.homes.members')}</p>
            <div className="flex flex-wrap gap-2">
                {(users.filter(u => home.memberIds.includes(u.id))).map(member => (
                    <div key={member.id} className="flex items-center gap-2 bg-slate-200 dark:bg-slate-700 px-2 py-1 rounded-full" style={{ borderLeft: `4px solid ${member.color}` }}>
                        {/* Avatar oculto pero mantenido en el DOM */}
                        <img 
                            src={member.avatar || '/user.svg'} 
                            alt={member.name} 
                            className="hidden" 
                            onError={(e) => {
                                const target = e.target as HTMLImageElement;
                                target.onerror = null;
                                target.src = '/user.svg';
                            }}
                        />
                        <span className="text-sm">{member.name}</span>
                        {/* Botón eliminar solo para admins y no a sí mismo */}
                        {home.adminIds.includes(currentUser.id) && member.id !== currentUser.id && (
                            <button
                                onClick={() => handleRemoveUser(home.id, member.id)}
                                disabled={loading[`remove_${member.id}`]}
                                className="ml-1 px-2 py-1 bg-red-500 hover:bg-red-600 text-white text-xs rounded-full disabled:bg-red-300"
                                title={t('settings.homes.removeUserTitle')}
                            >
                                ×
                            </button>
                        )}
                    </div>
                ))}
            </div>
            <div className="flex justify-end mt-4">
                <button
                    onClick={() => { setLeavingHomeId(home.id); handleLeaveHome(home.id); }}
                    disabled={loading[`leave_${home.id}`]}
                    className="px-4 py-2 bg-red-500 hover:bg-red-600 text-white rounded-md font-bold disabled:bg-red-300"
                >
                    {loading[`leave_${home.id}`] ? t('settings.homes.leaving') : t('settings.homes.leaveHome')}
                </button>
            </div>
        </div>
    ))}
</div>
                <div className="grid md:grid-cols-2 gap-8 pt-6 border-t border-slate-200 dark:border-slate-700">
                     <form onSubmit={handleCreateHome} className="space-y-3">
                        <h4 className="font-semibold">{t('settings.homes.createNew')}</h4>
                        <input
                            type="text"
                            value={newHomeName}
                            onChange={(e) => setNewHomeName(e.target.value)}
                            placeholder={t('settings.homes.homeNamePlaceholder')}
                            disabled={homesLimit.isLimited}
                            className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded disabled:opacity-60"
                        />
                        <button
                            type="submit"
                            disabled={loading['createHome'] || homesLimit.isLimited}
                            className="w-full py-2 px-4 bg-primary-600 hover:bg-primary-700 text-white rounded-md font-bold disabled:bg-primary-300"
                        >
                            {loading['createHome'] ? t('settings.homes.creating') : t('settings.homes.createHome')}
                        </button>
                        {homesLimit.isLimited && (
                            <p className="text-sm text-amber-700 dark:text-amber-300">
                                {homesLimit.message}
                            </p>
                        )}
                     </form>
                     {
                        !isPremium ? (
                            <div className="p-4 rounded-md bg-yellow-50 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-800">
                                <h4 className="font-semibold">{t('settings.invite.titlePremium')}</h4>
                                <p className="text-sm text-slate-700 dark:text-slate-300 mt-2">{t('settings.invite.premiumRequired')}</p>
                                <div className="mt-3">
                                    <button disabled={!purchaseEnabledOnPlatform} onClick={() => onViewChange(View.SUBSCRIPTION)} className="w-full py-2 px-4 bg-gradient-to-r from-yellow-400 via-amber-500 to-yellow-600 text-white font-bold rounded-md shadow-lg hover:shadow-2xl transition-all duration-300 relative overflow-hidden before:absolute before:inset-0 before:bg-white/20 before:opacity-0 hover:before:opacity-100 before:transition-opacity disabled:opacity-60 disabled:cursor-not-allowed">{purchaseEnabledOnPlatform ? t('settings.invite.buyPremium') : t('settings.invite.premiumDisabled')}</button>
                                </div>
                                <div className="mt-5 pt-4 border-t border-yellow-300/60 dark:border-yellow-700/60">
                                    <h5 className="font-semibold text-slate-800 dark:text-slate-200">{t('settings.anonymous.title')}</h5>
                                    <p className="text-sm text-slate-700 dark:text-slate-300 mt-1">
                                        {t('settings.anonymous.description')}
                                    </p>
                                    <form onSubmit={handleCreateAnonymousMember} className="space-y-2 mt-3">
                                        <select
                                            value={selectedHomeIdForAnonymous || ''}
                                            onChange={(e) => setSelectedHomeIdForAnonymous(e.target.value)}
                                            className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded"
                                        >
                                            {userHomes.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
                                        </select>
                                        <input
                                            type="text"
                                            value={anonymousMemberName}
                                            onChange={(e) => setAnonymousMemberName(e.target.value)}
                                            placeholder={t('settings.anonymous.namePlaceholder')}
                                            maxLength={16}
                                            className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded"
                                        />
                                        <button
                                            type="submit"
                                            disabled={loading['anonymousMember']}
                                            className="w-full py-2 px-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-md font-bold disabled:bg-emerald-300"
                                        >
                                            {loading['anonymousMember'] ? t('settings.homes.creating') : t('settings.anonymous.create')}
                                        </button>
                                    </form>
                                </div>
                            </div>
                        ) : (
                            <form onSubmit={handleCreateInviteLink} className="space-y-3">
                                <h4 className="font-semibold">{t('settings.invite.byUrl')}</h4>
                                <select value={selectedHomeIdForInvite || ''} onChange={e => setSelectedHomeIdForInvite(e.target.value)} required className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded">
                                    <option value="" disabled>{t('settings.homes.selectHome')}</option>
                                    {userHomes.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
                                </select>
                                <button type="submit" disabled={!selectedHomeIdForInvite || loading['invite']} className="w-full py-2 px-4 bg-secondary-500 hover:bg-secondary-600 text-white rounded-md font-bold disabled:bg-slate-400">{loading['invite'] ? t('settings.invite.generating') : t('settings.invite.generate')}</button>
                                {generatedInviteUrl && (
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium text-slate-700 dark:text-slate-300">{t('settings.invite.generatedLink')}</label>
                                        <input
                                            type="text"
                                            value={generatedInviteUrl}
                                            readOnly
                                            className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded text-sm"
                                        />
                                        <button
                                            type="button"
                                            onClick={async () => {
                                                try {
                                                    await navigator.clipboard.writeText(generatedInviteUrl);
                                                    showMessage('success', t('settings.invite.copied'));
                                                } catch {
                                                    showMessage('error', t('settings.invite.copyError'));
                                                }
                                            }}
                                            className="w-full py-2 px-4 bg-slate-700 hover:bg-slate-800 text-white rounded-md font-bold"
                                        >
                                            {t('settings.invite.copyLink')}
                                        </button>
                                    </div>
                                )}
                            </form>
                        )
                     }
                </div>
                 {!userHomes.length && <div className="text-center py-10 text-slate-500 dark:text-slate-400"><p>{t('settings.homes.none')}</p><p className="text-sm mt-2">{t('settings.homes.noneHint')}</p></div>}
            </div>

            {/* Sección de soporte y ayuda */}
            <div className="p-6 bg-white dark:bg-slate-800/50 rounded-xl shadow-md mt-6">
                <h3 className="text-xl font-bold mb-4 text-blue-600 dark:text-blue-400">{t('settings.support.title')}</h3>
                <p className="text-slate-600 dark:text-slate-300 mb-4">{t('settings.support.description')}</p>
                <button 
                    onClick={() => setShowBugReportModal(true)}
                    className="py-2 px-4 bg-blue-600 hover:bg-blue-700 text-white rounded-md font-bold"
                >
                    {t('settings.support.report')}
                </button>
            </div>

            {/* Sección para eliminar cuenta */}
            <div className="p-6 bg-white dark:bg-slate-800/50 rounded-xl shadow-md mt-6">
                <h3 className="text-xl font-bold mb-4 text-red-600 dark:text-red-400">{t('settings.danger.title')}</h3>
                <p className="text-slate-600 dark:text-slate-300 mb-4">{t('settings.danger.description')}</p>
                <button 
                    onClick={() => setShowDeleteAccountModal(true)}
                    className="py-2 px-4 bg-red-600 hover:bg-red-700 text-white rounded-md font-bold"
                >
                    {t('settings.danger.deleteAccount')}
                </button>
            </div>
            
            {isNative && <div className="p-6 bg-white dark:bg-slate-800/50 rounded-xl shadow-md text-center"><button onClick={handleReviewClick} className="font-semibold text-primary-600 dark:text-primary-400">{t('settings.review.cta')}</button></div>}

            {!USE_FIREBASE && togglePremium && (
                <div className="p-6 bg-yellow-100 dark:bg-yellow-900/50 rounded-xl shadow-md text-center">
                    <h4 className="font-bold text-yellow-800 dark:text-yellow-200">{t('settings.dev.title')}</h4>
                    <p className="text-sm text-yellow-700 dark:text-yellow-300 mb-2">{t('settings.dev.description')}</p>
                    <button onClick={togglePremium} className="bg-yellow-500 text-white font-bold py-2 px-4 rounded-lg">
                        {isPremium ? t('settings.dev.switchFree') : t('settings.dev.switchPremium')}
                    </button>
                </div>
            )}
            {/* Modal de confirmación para dejar la casa */}
            {confirmLeaveHomeId && (
              <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-40">
                <div className="bg-white dark:bg-slate-800 rounded-lg shadow-lg p-6 max-w-sm w-full">
                  <h3 className="text-lg font-bold mb-2 text-slate-900 dark:text-white">{t('settings.homes.leaveConfirmTitle')}</h3>
                  <p className="mb-4 text-slate-600 dark:text-slate-300">{t('settings.homes.leaveConfirmDesc')}</p>
                  <div className="flex justify-end gap-2">
                    <button onClick={cancelLeave} className="px-4 py-2 rounded bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200 font-semibold">{t('common.cancel')}</button>
                    <button onClick={confirmLeave} className="px-4 py-2 rounded bg-red-600 text-white font-bold hover:bg-red-700 disabled:bg-red-300" disabled={loading[`leave_${confirmLeaveHomeId}`]}>{loading[`leave_${confirmLeaveHomeId}`] ? t('settings.homes.leaving') : t('settings.homes.leave')}</button>
                  </div>
                </div>
              </div>
            )}
            {/* Modal de confirmación para eliminar usuario */}
            {confirmRemove && (
              <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-40">
                <div className="bg-white dark:bg-slate-800 rounded-lg shadow-lg p-6 max-w-sm w-full">
                  <h3 className="text-lg font-bold mb-2 text-slate-900 dark:text-white">{t('settings.homes.removeConfirmTitle', { name: confirmRemove.user.name })}</h3>
                  <p className="mb-4 text-slate-600 dark:text-slate-300">{t('settings.homes.irreversible')}</p>
                  <div className="flex justify-end gap-2">
                    <button onClick={cancelRemoveUser} className="px-4 py-2 rounded bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200 font-semibold">{t('common.cancel')}</button>
                    <button onClick={confirmRemoveUser} className="px-4 py-2 rounded bg-red-600 text-white font-bold hover:bg-red-700 disabled:bg-red-300" disabled={loading[`remove_${confirmRemove.user.id}`]}>{loading[`remove_${confirmRemove.user.id}`] ? t('settings.homes.removing') : t('settings.homes.remove')}</button>
                  </div>
                </div>
              </div>
            )}
            {/* Modal de feedback de invitación */}
            {inviteFeedback && (
              <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-40">
                <div className={`bg-white dark:bg-slate-800 rounded-lg shadow-lg p-6 max-w-sm w-full border-l-4 ${inviteFeedback.type === 'success' ? 'border-green-500' : 'border-red-500'}` }>
                  <h3 className={`text-lg font-bold mb-2 ${inviteFeedback.type === 'success' ? 'text-green-700 dark:text-green-300' : 'text-red-700 dark:text-red-300'}`}>{inviteFeedback.type === 'success' ? t('settings.invite.ready') : t('common.error')}</h3>
                  <p className="mb-4 text-slate-600 dark:text-slate-300">{inviteFeedback.text}</p>
                  <div className="flex justify-end">
                    <button onClick={() => setInviteFeedback(null)} className="px-4 py-2 rounded bg-primary-600 text-white font-bold hover:bg-primary-700">{t('common.close')}</button>
                  </div>
                </div>
              </div>
            )}
            {/* Modal de notificación para usuario eliminado */}
            {removedUserNotification && (
              <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-40">
                <div className="bg-white dark:bg-slate-800 rounded-lg shadow-lg p-6 max-w-sm w-full border-l-4 border-red-500">
                  <h3 className="text-lg font-bold mb-2 text-red-700 dark:text-red-300">Usuario eliminado</h3>
                  <p className="mb-4 text-slate-600 dark:text-slate-300">
                    <span className="font-semibold">{removedUserNotification.userName}</span> ha sido eliminado de <span className="font-semibold">{removedUserNotification.homeName}</span>.
                  </p>
                  <p className="mb-4 text-slate-600 dark:text-slate-300">
                    {t('settings.homes.removedUserImpact')}
                  </p>
                  <div className="flex justify-end">
                    <button onClick={closeRemovedUserNotification} className="px-4 py-2 rounded bg-primary-600 text-white font-bold hover:bg-primary-700">{t('upgrade.understood')}</button>
                  </div>
                </div>
              </div>
            )}

            {/* Modal de reporte de errores */}
            <BugReportModal 
              isOpen={showBugReportModal}
              onClose={() => setShowBugReportModal(false)}
            />

            {/* Modal de eliminación de cuenta */}
            {showDeleteAccountModal && (
              <DeleteAccountModal 
                isOpen={showDeleteAccountModal}
                onClose={() => setShowDeleteAccountModal(false)} 
                onConfirmDelete={async (password) => {
                  const result = await deleteAccount(password);
                  if (result.success) {
                    // El usuario será redirigido automáticamente al cerrar sesión
                  } else {
                    showMessage('error', result.message);
                    setShowDeleteAccountModal(false);
                  }
                }} 
              />
            )}

            {/* Modal de cancelación de suscripción */}
            {showCancelSubscriptionModal && (
              <CancelSubscriptionModal 
                isOpen={showCancelSubscriptionModal}
                onClose={() => setShowCancelSubscriptionModal(false)} 
                onConfirmCancel={handleCancelSubscription}
              />
            )}
        </div>
    );
};

export default SettingsPage;
