import { useState, useEffect } from 'react';

type Platform = 'web' | 'android' | 'ios';

// Detecta plataforma priorizando runtime real de Capacitor.
const detectPlatform = (): Platform => {
    const cap = (typeof window !== 'undefined') ? (window as any).Capacitor : null;
    if (cap?.isNativePlatform?.()) {
        const capPlatform = cap.getPlatform?.();
        if (capPlatform === 'android' || capPlatform === 'ios') {
            return capPlatform;
        }
    }

    const ua = navigator.userAgent.toLowerCase();
    
    // Detectar Android
    if (/android/.test(ua)) {
        return 'android';
    }
    
    // Detectar iOS (iPhone, iPad, iPod)
    if (/iphone|ipad|ipod/.test(ua)) {
        return 'ios';
    }
    
    // Si no es ninguno de los anteriores, es web
    return 'web';
}

export const usePlatform = () => {
    const [platform, setPlatform] = useState<Platform>(() => {
        // Detectar inmediatamente en la inicialización
        if (typeof window !== 'undefined') {
            return detectPlatform();
        }
        return 'web';
    });

    useEffect(() => {
        setPlatform(detectPlatform());
    }, []);

    return {
        platform,
        isNative: platform === 'android' || platform === 'ios',
        isWeb: platform === 'web'
    };
}
